-- Notation normalization — formatting-only fixes (raw LaTeX repaired, formulas wrapped as \(...\) in questions
-- and clean Unicode in flashcards; leaked distractor-category labels stripped). Science/wording unchanged.
-- Applied live directly; this file is the record. UPDATE by id, idempotent.

BEGIN;

UPDATE questions SET question_text = 'Neon and sodium occupy adjacent positions in the same period, yet neon''s first ionization energy is roughly four times larger than sodium''s. Holding period constant, which factor most directly accounts for neon being so much harder to ionize than its right-hand neighbor sodium?', options = '[{"text":"Neon''s smaller atomic radius lets its valence electrons pair off, and electron pairing alone stabilizes the atom against losing an electron.","label":"A"},{"text":"Neon''s outermost electron sits in a filled \\(n=2\\) shell where it feels a higher \\(Z_\\text{eff}\\), whereas sodium''s removed electron is a lone \\(3s^1\\) electron screened into a new shell.","label":"B"},{"text":"Removing an electron from neon would expose its filled \\(2p^6\\) subshell, and emptying a subshell releases energy that opposes ionization.","label":"C"},{"text":"Neon holds more protons than sodium, so its greater nuclear charge binds the valence electrons more tightly than sodium''s does.","label":"D"}]'::jsonb, explanation = 'This item targets periodic trends in first ionization energy, specifically how electron configuration and effective nuclear charge govern how tightly a valence electron is held. The hinge is that neon and sodium sit at a period boundary: neon (\(1s^2\,2s^2\,2p^6\)) loses an electron from a completed \(n=2\) shell, where that electron experiences a high \(Z_\text{eff} = Z - S\) and lies close to the nucleus, while sodium (\([\text{Ne}]3s^1\)) loses a single \(3s^1\) electron that occupies a new, more distant shell and is heavily screened by the underlying neon core. The combination of a filled, low-lying shell and high \(Z_\text{eff}\) makes neon''s electron far harder to remove, which is why first ionization energy collapses sharply on crossing into the next period, making B correct.
(Choice A) Smaller radius does correlate with higher ionization energy, but pairing of electrons does not by itself stabilize an atom against ionization; in fact, electron-electron repulsion within a paired orbital can slightly lower ionization energy, so pairing is not the operative factor here.
(Choice C) Removing one electron from \(2p^6\) yields \(2p^5\); it does not empty the subshell, and no special energy is released by partially depleting a filled subshell. The stability of the filled configuration raises ionization energy because the electron is tightly bound, not because of an energy release upon removal.
(Choice D) Sodium actually has one more proton than neon (\(Z=11\) versus \(Z=10\)), so a claim that neon holds more protons reverses the actual nuclear-charge relationship; the relevant quantity is \(Z_\text{eff}\) felt by the removed electron, not total proton count.
Skill 2' WHERE id = 'be566b2e-958e-41af-bae3-a810220ba650';
UPDATE questions SET question_text = 'A biochemist assays a purified enzyme at a fixed, low total enzyme concentration and a substrate concentration far below the enzyme''s \(K_m\) (\([S] \ll K_m\)), so that the enzyme remains almost entirely in the free, unbound state. To predict how the initial reaction velocity will respond as the substrate concentration is varied within this low range, which single kinetic parameter would most likely give the best prediction of the rate?', options = '[{"text":"\\(V_{max}\\)","label":"A"},{"text":"\\(K_m\\)","label":"B"},{"text":"\\(k_{cat}/K_m\\)","label":"C"},{"text":"\\(k_{cat}\\)","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because, when \([S] \ll K_m\) and the enzyme is mostly unbound, the Michaelis-Menten equation simplifies so that velocity is governed by the ratio \(k_{cat}/K_m\). The textbook states: "Under condition when \([S] \ll K_\text{M}\), the Michaelis-Menten equation becomes \(v_0 = (k_{cat}/K_\text{M})[E_0][S]\). This really describes a biomolecular rate constant \((k_{cat}/K_\text{M})\), with units of \(\text{M}^{-1}\text{s}^{-1}\), for the conversion of free substrate to product." It also notes that "when \(S \ll K_\text{M}\), \(v = V_\text{M}S/K_\text{M} = k_3 E_0 S/K_\text{M} \ldots k_3/K_\text{M}\) has units of \(\text{M}^{-1}\text{s}^{-1}\), the same as a second-order rate constant," so \(k_{cat}/K_m\) is the apparent second-order rate constant that predicts the rate in this low-\([S]\) regime. (Choice A) is incorrect: \(V_{max}\) describes the opposite, saturating regime — the textbook gives "when \(S \gg K_\text{M}\), \(v = V_\text{M} = k_3 E_0\)" (zero order in \(S\)) and "For all reactions, \(V_\text{M} = k_{cat}E_0\)," so \(V_{max}\) is the high-\([S]\) plateau and depends on enzyme concentration, not the low-\([S]\) rate. (Choice B) is incorrect: \(K_m\) is "the substrate concentration at which the initial velocity is half of \(V_\text{M}\)" — a concentration that locates the midpoint of the curve, not a rate constant that predicts velocity at low \([S]\). (Choice C) is correct: at \([S] \ll K_m\) the simplified equation \(v_0 = (k_{cat}/K_m)[E_0][S]\) makes \(k_{cat}/K_m\) the second-order rate constant governing catalysis while the enzyme is mostly free. (Choice D) is incorrect: \(k_{cat}\) is "the catalytic rate constant, with units of \(\text{s}^{-1}\) ... often called the turnover number," which characterizes turnover of bound substrate (the saturated enzyme); on its own it does not set the low-\([S]\) rate, which depends on the \(k_{cat}/K_m\) ratio. This is a Scientific Reasoning and Problem Solving question because you must apply the simplified low-substrate form of the Michaelis-Menten equation to identify which kinetic constant governs the rate when the enzyme is mostly unbound, rather than recalling a single definition.' WHERE id = '9b0af8f8-06c4-4ac1-834e-2e971687bf0d';
UPDATE questions SET question_text = 'A technician monitoring a sample notes that one neutral atom of an element simultaneously captures a free neutron into its nucleus and ejects one of its electrons. Tracking the atom before and after this combined event, what happens to its mass number, its net charge, and its identity as an element?', options = '[{"text":"Mass number stays the same, net charge becomes \\(+1\\), and the element changes.","label":"A"},{"text":"Mass number increases by \\(1\\), net charge becomes \\(-1\\), and the element stays the same.","label":"B"},{"text":"Mass number increases by \\(1\\), net charge stays at \\(0\\), and the element changes.","label":"C"},{"text":"Mass number increases by \\(1\\), net charge becomes \\(+1\\), and the element stays the same.","label":"D"}]'::jsonb, explanation = 'This question tests the independence of proton, neutron, and electron counts in defining mass number, net charge, and element identity. Mass number \(A\) is the sum of protons and neutrons, so capturing one neutron raises \(A\) by \(1\); it does not depend on electrons. Net charge is set by the difference between protons and electrons, so losing one electron from a neutral atom (equal counts) leaves protons exceeding electrons by one, giving a charge of \(+1\). Element identity is fixed solely by the atomic number \(Z\) (proton count), and neither a neutron capture nor an electron loss alters \(Z\), so the element is unchanged. The result is mass number \(+1\), net charge \(+1\), element unchanged. (Choice A) A neutron capture adds to the nucleon total, so the mass number must rise by \(1\) rather than remain constant; additionally, neither event changes the proton count, so the element cannot change. (Choice B) Removing an electron from a neutral atom leaves one more proton than electron, producing a \(+1\) charge, not \(-1\); a \(-1\) charge would require gaining an electron. (Choice C) Net charge cannot remain \(0\) once an electron is lost without a compensating proton change, and element identity is tied to \(Z\), which the neutron and electron events leave untouched, so the element does not change. Skill 2' WHERE id = 'd853870a-240d-46a1-a13f-9a65e82b4179';
UPDATE questions SET question_text = 'A researcher compares two enzymes acting on the same substrate at equal enzyme concentrations. Enzyme P has \(k_{cat}=1000\ \text{s}^{-1}\) and \(K_m=1\ \text{mM}\) (so \(k_{cat}/K_m=1.0\times10^{6}\ \text{M}^{-1}\text{s}^{-1}\)), whereas enzyme Q has \(k_{cat}=200\ \text{s}^{-1}\) and \(K_m=0.01\ \text{mM}\) (so \(k_{cat}/K_m=2.0\times10^{7}\ \text{M}^{-1}\text{s}^{-1}\)). If the assay is run at a saturating substrate concentration far above both \(K_m\) values, which enzyme would most likely convert substrate to product faster?', options = '[{"text":"Enzyme Q, because it has the higher \\(k_{cat}/K_m\\)","label":"A"},{"text":"Enzyme Q, because it has the lower \\(K_m\\)","label":"B"},{"text":"Both convert substrate at equal rates, because at saturation the velocity no longer depends on the enzyme''s kinetic constants","label":"C"},{"text":"Enzyme P, because it has the higher \\(k_{cat}\\)","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because at a substrate concentration far above both \(K_m\) values the reaction is saturated, and the textbook states that "when \(S \gg K_\text{M}\), \(v = V_\text{M} = k_3 E_0\)" — that is, the velocity approaches \(V_{max}=k_{cat}[E_0]\) and becomes "zero order with respect to \(S\) and first order in \(E\)" (line 27089). Because "\(V_\text{M} = k_{cat}E_0\)" for all reactions (line 27225) and the two enzymes are present at equal concentration, the enzyme with the higher \(k_{cat}\) — the turnover number, "a measure of how many bound substrate molecules ''turnover'' or form product in 1 second" (line 27366) — turns substrate over faster. Enzyme P (\(k_{cat}=1000\ \text{s}^{-1}\)) exceeds enzyme Q (\(k_{cat}=200\ \text{s}^{-1}\)), so P wins at saturation despite having the lower \(k_{cat}/K_m\). (Choice A) is wrong because \(k_{cat}/K_m\) governs the rate only "Under condition when \([S] \ll K_\text{M}\)," where "the Michaelis-Menten equation becomes \(v_0 = (k_{cat}/K_\text{M})[E_0][S]\)" (line 27368); at the saturating \([S]\) in this scenario that low-\([S]\) regime does not apply, so Q''s higher specificity constant does not make it faster. (Choice B) is wrong because \(K_m\) is "the substrate concentration at which the initial velocity is half of \(V_\text{M}\)" (line 27363); once \([S]\) is far above both \(K_m\) values both enzymes are near \(V_{max}=k_{cat}[E_0]\), so the lower \(K_m\) of Q confers no rate advantage at saturation. (Choice C) is wrong because at saturation the velocity still depends on a kinetic constant: "\(V_\text{M} = k_{cat}E_0\)" (line 27225), so it scales directly with \(k_{cat}\) rather than becoming equal for the two enzymes. (Choice D) is correct: at saturating \([S]\) the velocity approaches \(V_{max}=k_{cat}[E_0]\) (lines 27089, 27225), and with equal \([E]\) the enzyme with the higher \(k_{cat}\) — enzyme P — converts substrate faster. This is a Scientific Reasoning and Problem Solving question because you must apply the regime dependence of enzyme kinetics, recognizing that \(k_{cat}/K_m\) governs the rate at low \([S]\) while \(k_{cat}\) governs the rate at saturation, and use the given numbers to determine which enzyme is faster under saturating conditions.' WHERE id = '87aeb3ff-3d21-4b3a-9404-7b1aba1a53b1';
UPDATE questions SET question_text = 'When hot concentrated base reacts with chlorine, hypochlorite ion disproportionates according to the balanced equation \(3\,\text{ClO}^- \rightarrow 2\,\text{Cl}^- + \text{ClO}_3^-\). In this self-redox process, chlorine begins in a single oxidation state in \(\text{ClO}^-\) and ends distributed between the two products. What are the two oxidation states that the disproportionating chlorine reaches in the products \(\text{Cl}^-\) and \(\text{ClO}_3^-\), respectively?', options = '[{"text":"\\(+1\\) in \\(\\text{Cl}^-\\) and \\(+7\\) in \\(\\text{ClO}_3^-\\)","label":"A"},{"text":"\\(-1\\) in \\(\\text{Cl}^-\\) and \\(+3\\) in \\(\\text{ClO}_3^-\\)","label":"B"},{"text":"\\(0\\) in \\(\\text{Cl}^-\\) and \\(+5\\) in \\(\\text{ClO}_3^-\\)","label":"C"},{"text":"\\(-1\\) in \\(\\text{Cl}^-\\) and \\(+5\\) in \\(\\text{ClO}_3^-\\)","label":"D"}]'::jsonb, explanation = 'This is a General Chemistry question that falls under the content category ''Stoichiometry (GC)''. The answer to this question is D because disproportionation requires the single starting element to split into one product where it is reduced and one where it is oxidized, and the oxidation-number bookkeeping fixes both values exactly. In the reactant \(\text{ClO}^-\), oxygen is assigned \(-2\), so chlorine must satisfy \((\text{Cl}) + (-2) = -1\), giving \(\text{Cl} = +1\). In \(\text{Cl}^-\) the ion charge is the oxidation number, so \(\text{Cl} = -1\) (chlorine is reduced, gaining 2 electrons per atom). In \(\text{ClO}_3^-\), the three oxygens contribute \(3\times(-2) = -6\), and the overall \(-1\) charge requires \((\text{Cl}) + (-6) = -1\), so \(\text{Cl} = +5\) (chlorine is oxidized, losing 4 electrons per atom). The electron ledger balances: the 2 chlorines reduced from \(+1\) to \(-1\) gain \(2\times2 = 4\) electrons, exactly matching the 1 chlorine oxidized from \(+1\) to \(+5\) that loses 4 electrons. Thus the disproportionating chlorine reaches \(-1\) and \(+5\). (Choice A) This reverses the direction of electron flow by claiming chlorine is oxidized to \(+1\) in \(\text{Cl}^-\) (the starting value) and pushed all the way to \(+7\) in \(\text{ClO}_3^-\); \(+7\) is the oxidation state in perchlorate \(\text{ClO}_4^-\), and \(\text{Cl}^-\) is the reduced product at \(-1\), not \(+1\). It treats both products as oxidized and overshoots the chlorate oxidation number. (Choice B) This keeps the correct \(-1\) for \(\text{Cl}^-\) but assigns \(+3\) to chlorine in \(\text{ClO}_3^-\); \(+3\) is the oxidation state of chlorine in chlorite \(\text{ClO}_2^-\), not chlorate. For \(\text{ClO}_3^-\) the three oxygens force \(\text{Cl} = +5\), so this misidentifies the oxyanion by confusing chlorate with chlorite. (Choice C) This assigns \(0\) to chlorine in \(\text{Cl}^-\), treating it as elemental \(\text{Cl}_2\); a monatomic ion''s oxidation number equals its charge, so \(\text{Cl}^-\) is \(-1\), not \(0\). Reading the reduced product as oxidation state \(0\) understates the electron gain and breaks the electron balance with the \(+5\) product. Skill 2' WHERE id = 'b3dd64c8-8df8-46b6-bfdc-ad513e28655b';
UPDATE questions SET question_text = 'A geneticist images a cultured animal cell at metaphase and finds that every replicated chromosome is bioriented except one, whose single unattached kinetochore has not yet captured spindle microtubules from either pole; all spindle motors, cohesins, and separase are otherwise functional. The cell is monitored over the next several hours. What is the cell''s most likely behavior?', options = '[{"text":"It arrests before mitosis because the G2 checkpoint detects the incompletely processed chromosome and bars entry into the mitotic phase.","label":"A"},{"text":"It halts at metaphase and does not enter anaphase, because the M checkpoint blocks sister-chromatid separation until every kinetochore is properly anchored to the spindle.","label":"B"},{"text":"It proceeds into anaphase on schedule and produces two daughter cells, one of which is left missing the chromosome that was unattached at the equator.","label":"C"},{"text":"It proceeds into anaphase because the M checkpoint triggers a halt only when all kinetochores remain unattached, and a single lagging chromosome is tolerated.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Cell Cycle & Mitosis (BIO)''. The answer is B because the M checkpoint, also called the spindle checkpoint, monitors kinetochore-spindle attachment at metaphase and will not allow the cycle to advance into anaphase until every kinetochore is anchored. The text states that the M checkpoint "determines whether all the sister chromatids are correctly attached to the spindle microtubules," and that "[b]ecause the separation of the sister chromatids during anaphase is an irreversible step, the cycle will not proceed until the kinetochores of each pair of sister chromatids are firmly anchored to at least two spindle fibers arising from opposite poles of the cell." Because anaphase cannot be undone, a single unattached kinetochore is sufficient to keep the cell halted in metaphase rather than risk an unequal partition. (Choice A) is wrong because the G2 checkpoint acts before the mitotic phase to verify chromosome replication and DNA integrity, not kinetochore attachment, which is assessed only once the cell is already in metaphase. (Choice B) is correct because the unsatisfied spindle checkpoint blocks the irreversible anaphase transition until the last kinetochore is anchored. (Choice C) is wrong because allowing anaphase to proceed on schedule is exactly the missegregation outcome the M checkpoint exists to prevent; the checkpoint holds the cell rather than letting it divide unequally. (Choice D) is wrong because the checkpoint requires that every kinetochore be attached, so even one unanchored kinetochore is enough to maintain the halt rather than being tolerated. This is a Scientific Reasoning and Problem Solving question because it requires predicting a cell''s behavior by combining the surveillance role of the spindle checkpoint with the irreversibility of anaphase to determine that division is withheld.' WHERE id = '4aa63727-2f3b-4a9a-b838-82937f47fef9';
UPDATE questions SET question_text = 'A developmental biologist grafts dorsal "organizer" cells from a donor amphibian embryo into the ventral (belly) region of a host embryo and observes that a complete second notochord and body axis develops at the graft site. Lineage labeling reveals that most of the cells making up this second axis carry the host''s marker, not the donor''s. What does this result most strongly indicate about how the second axis forms?', options = '[{"text":"The second notochord is built entirely from the dividing descendants of the grafted dorsal cells, which proliferate in place without instructing any surrounding host tissue.","label":"A"},{"text":"The grafted dorsal cells act as a local inducer, signaling competent neighboring host cells to change fate, so most of the second axis is built from recruited host tissue.","label":"B"},{"text":"The grafted dorsal cells anchor to the host belly cells through gap junctions, and the passage of ions such as \\(\\text{Ca}^{2+}\\) directly between the cytoplasms drives the host cells to form a notochord.","label":"C"},{"text":"The grafted dorsal cells release a hormone into the embryo''s bloodstream that travels to and respecifies distant host cells into notochord tissue.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Mechanisms of Development''. The answer is B because the host-derived marker dominating the second axis shows the graft did not build the structure itself but instead signaled nearby host cells to change their fate, the defining feature of induction. Local, short-range signaling of this kind is paracrine: signals "move by diffusion through the extracellular matrix" to "neighboring cells," and in embryological development "this process of stimulating a group of neighboring cells may help to direct the differentiation of identical cells." The host cells could respond because, at this stage, they are still competent and "not yet fully committed... to develop into specific cell types," so "adjacent cells are able to compensate" and adopt new fates; the graft supplies the instructive signal rather than the cellular building blocks. (Choice A) is the reversed reading in which the inducer is treated as the sole responder; it is contradicted by the lineage data showing the axis is mostly host-derived, not donor-derived. (Choice B) is correct because the host-marked second axis reflects competent host cells responding to an inductive signal released by the graft. (Choice C) confuses paracrine induction with gap-junction signaling, which only lets "small molecules or ions, such as calcium ions (\(\text{Ca}^{2+}\))" pass between adjacent cells while "large molecules like proteins and DNA cannot fit," and cannot account for instructing a whole field of cells to build an axis. (Choice D) misapplies endocrine signaling, in which "hormones travel the large distances between endocrine cells and their target cells via the bloodstream," whereas this is a strictly local effect at the graft site. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental graft-and-lineage result to infer the underlying signaling mechanism rather than recalling a stated fact.' WHERE id = 'fcb1fb9d-4fc9-4ede-ab8b-d46b1ea4acff';
UPDATE questions SET question_text = 'A pharmacologist maps a single chemical synapse and finds neurotransmitter-filled vesicles concentrated in one of the two apposed membranes and ligand-gated receptor proteins concentrated in the other. From this architecture, the pharmacologist predicts that an electrical signal arriving at this synapse can be chemically relayed in only one direction. Which arrangement of vesicles and receptors accounts for that one-way relay?', options = '[{"text":"Vesicles sit in the postsynaptic membrane and release transmitter back across the cleft toward the axon terminal, which carries the receptors.","label":"A"},{"text":"The postsynaptic membrane both binds transmitter at its receptors and stores transmitter in vesicles that it releases across the cleft.","label":"B"},{"text":"Vesicles are clustered in the presynaptic axon terminal and the postsynaptic membrane bears only receptors, so transmitter crosses the cleft one way.","label":"C"},{"text":"Vesicles are split evenly between the two membranes, letting either side release transmitter and pass the signal across the cleft in either direction.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Neuron & Glial Cell Structure''. The answer is C because the neurotransmitter-containing vesicles are confined to the presynaptic axon terminal, while the postsynaptic membrane carries only receptor proteins, so transmitter can be released from just one side and the synapse relays the signal in a single direction across the cleft. OpenStax A&P 2e lists the common parts of a chemical synapse as a presynaptic element, "neurotransmitter (packaged in vesicles)," a synaptic cleft, receptor proteins, and a postsynaptic element, and states that "the presynaptic element is the motor neuron''s axon terminals" while the receptor protein and postsynaptic element are on the receiving cell; \(\text{Ca}^{2+}\) entry "facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis... into the... synaptic cleft." OpenStax Biology 2e adds that neurotransmitters are released "from the presynaptic cell (the cell emitting the signal)" and then "binds the receptor on the surface of the postsynaptic cell," confirming that release is a presynaptic event and reception a postsynaptic one. Because only the presynaptic terminal holds vesicles, transmitter can only flow toward the receptor-bearing postsynaptic membrane, which is what makes chemical transmission unidirectional. (Choice A) is incorrect because it reverses the sending and receiving sides: the vesicles are presynaptic (in the axon terminal) and the receptors are postsynaptic, not the other way around. (Choice B) is incorrect because, although the postsynaptic membrane truly does bear receptors, carrying receptors does not mean it stores or releases transmitter vesicles, which remain in the presynaptic terminal. (Choice C) is correct because vesicles are clustered in the presynaptic axon terminal and the postsynaptic membrane bears only receptors, restricting release to one side and transmission to one direction. (Choice D) is incorrect because vesicles are confined to the presynaptic terminal rather than split between membranes, and that confinement is precisely what prevents the synapse from passing transmitter in either direction. This is a Scientific Reasoning and Problem Solving question because it requires the test-taker to reason from the spatial architecture of the synapse to a functional prediction about the direction of signal transmission, rather than simply recalling where vesicles are located.' WHERE id = '06109450-ee02-4e2c-b47e-11018d84f27f';
UPDATE questions SET question_text = 'A myelinated axon conducts impulses by saltatory conduction: the internodal membrane is wrapped in insulating myelin, while the bare nodes of Ranvier are spaced along the axon. A physiologist predicts which membrane proteins must be densely enriched at each node so that the action potential can be regenerated there as it leaps down the axon. Which channels does the prediction identify?', options = '[{"text":"Acetylcholine receptors, which relay the impulse chemically across each myelin gap","label":"A"},{"text":"Voltage-gated \\(\\text{Ca}^{2+}\\) channels, whose \\(\\text{Ca}^{2+}\\) influx regenerates the action potential at the node","label":"B"},{"text":"Voltage-gated \\(\\text{Na}^+\\) channels, whose \\(\\text{Na}^+\\) influx regenerates the action potential at the node","label":"C"},{"text":"\\(\\text{Na}^+\\)/\\(\\text{K}^+\\) ATPase pumps, whose active inward pumping of \\(\\text{Na}^+\\) depolarizes the node","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is C because the nodes of Ranvier contain voltage-gated \(\text{Na}^+\) (and \(\text{K}^+\)) channels, and it is the flow of ions through the \(\text{Na}^+\) channels in particular that regenerates the action potential over and over at each node. Because the internodal membrane is insulated by myelin and lacks voltage-gated channels, the depolarization spreads passively between nodes and must be actively rebuilt at each bare node; this requires a high density of voltage-gated \(\text{Na}^+\) channels so that \(\text{Na}^+\) rushing in renews the impulse before the spreading charge falls below threshold. Saltatory conduction works precisely because these channels are clustered only at the nodes, letting the action potential ''jump'' from node to node. (Choice A) Acetylcholine receptors mediate chemical transmission at synapses, not regeneration within a single axon, where the impulse propagates electrically through voltage-gated channels. (Choice B) Voltage-gated \(\text{Ca}^{2+}\) channels open at the axon terminal to trigger neurotransmitter release, not at the nodes to regenerate the impulse, which the text attributes specifically to \(\text{Na}^+\) channels. (Choice C) Correct: voltage-gated \(\text{Na}^+\) channels enriched at each node carry the inward \(\text{Na}^+\) current that regenerates the action potential as it leaps down the axon. (Choice D) The \(\text{Na}^+\)/\(\text{K}^+\) ATPase pumps \(\text{Na}^+\) outward (and \(\text{K}^+\) inward) to maintain the resting gradient and consumes ATP; regeneration is by passive \(\text{Na}^+\) influx through voltage-gated channels, not by the pump. This is a Scientific Reasoning and Problem Solving question because it requires using the insulating property of the internode to predict which specific channel type must be concentrated at a node to rebuild the impulse, rather than recalling a definition.' WHERE id = 'a324affd-c951-4f6c-a757-ad920bc5b600';
UPDATE questions SET question_text = 'A sensory neuron is stimulated twice in succession: first by a stimulus that depolarizes its membrane to exactly the -55 mV threshold, and then by a stimulus that drives the membrane far past threshold. An electrophysiologist records the action potentials evoked in each case and is asked to predict how the two recordings differ.', options = '[{"text":"The far-above-threshold stimulus produces action potentials that reach a higher peak voltage, but it fires them at the same frequency as the threshold stimulus.","label":"A"},{"text":"Both stimuli produce same-peak action potentials, but the far-above-threshold stimulus makes each spike rise to its peak faster and reach the axon terminal sooner.","label":"B"},{"text":"Both stimuli produce action potentials that peak at the same voltage, but the far-above-threshold stimulus fires them at a higher frequency.","label":"C"},{"text":"Both stimuli produce same-peak action potentials at the same frequency, but the far-above-threshold stimulus releases more neurotransmitter per spike.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is C because, once threshold is crossed, every action potential in a given axon is an all-or-none event that runs the identical course to the same +30 mV peak, so the only way a neuron encodes a stronger stimulus is by firing more action potentials per unit time. The text states that "a stronger stimulus, which might depolarize the membrane well past threshold, will not make a ''bigger'' action potential" and that "all action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another," while "stronger stimuli will initiate multiple action potentials more quickly" (A&P 21981-21986). Thus the far-above-threshold stimulus changes firing frequency, not spike amplitude; the spike''s rising speed and conduction velocity are fixed by \(\text{Na}^+\)/\(\text{K}^+\) channel kinetics, axon diameter, and myelination rather than by stimulus size (A&P 22061-22067), and the transmitter released downstream is gated by the all-or-none \(\text{Ca}^{2+}\) influx of an identical spike (Biology 2e 46093-46095). (Choice A) is wrong because it reverses which variable changes, claiming amplitude coding when the text says all spikes peak at the same +30 mV and only frequency rises. (Choice B) is a tempting partial truth: it correctly keeps the peak constant but wrongly ties the spike''s rise time and conduction speed to stimulus strength, when those are set by channel kinetics, axon diameter, and myelination, not by how hard the membrane is pushed past threshold. (Choice C) is correct because both spikes reach the same peak voltage and the only difference is the higher firing frequency driven by the stronger stimulus. (Choice D) is wrong because transmitter release per spike is gated by the all-or-none \(\text{Ca}^{2+}\) influx of an identical action potential, so a larger upstream stimulus does not load each individual spike with more neurotransmitter. This is a Scientific Reasoning and Problem Solving question because it requires applying the all-or-none principle to a two-stimulus scenario and rejecting amplitude-, kinetics-, and release-based traps to predict that intensity is encoded by frequency alone.' WHERE id = 'ce8052f6-d587-4ec6-9c33-dced50b92ad0';
UPDATE questions SET question_text = 'An action potential travels down a motor neuron and arrives at the synaptic end bulb, where it depolarizes the terminal membrane and triggers the release of neurotransmitter into the synaptic cleft. The voltage-gated ion channel that opens in the end-bulb membrane to directly set this release in motion is the:', options = '[{"text":"voltage-gated potassium (\\(\\text{K}^+\\)) channel, which opens at the terminal so that \\(\\text{K}^+\\) exits the end bulb and drives neurotransmitter release","label":"A"},{"text":"ligand-gated sodium (\\(\\text{Na}^+\\)) channel, which opens in the end bulb as the action potential arrives and admits \\(\\text{Na}^+\\) to release transmitter","label":"B"},{"text":"mechanically gated chloride (\\(\\text{Cl}^-\\)) channel, which opens at the terminal to admit \\(\\text{Cl}^-\\) and cause the vesicles to fuse","label":"C"},{"text":"voltage-gated calcium (\\(\\text{Ca}^{2+}\\)) channel, which opens as the terminal depolarizes and admits \\(\\text{Ca}^{2+}\\) to trigger vesicle fusion","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is D because the arriving action potential depolarizes the synaptic end-bulb membrane, opening voltage-gated \(\text{Ca}^{2+}\) channels that let \(\text{Ca}^{2+}\) flow into the terminal and trigger vesicle fusion. OpenStax Anatomy & Physiology 2e states that "When an action potential reaches the axon terminals, voltage-gated \(\text{Ca}^{2+}\) channels in the membrane of the synaptic end bulb open," after which "the concentration of \(\text{Ca}^{2+}\) increases inside the end bulb" and "the \(\text{Ca}^{2+}\) facilitates the merging of the vesicle with the presynaptic membrane." OpenStax Biology 2e confirms this sequence: depolarization "causes voltage-gated \(\text{Ca}^{2+}\) channels to open," and "Calcium ions entering the cell initiate a signaling cascade that causes... synaptic vesicles... to fuse with the presynaptic membrane." The trigger is therefore \(\text{Ca}^{2+}\) entry through a voltage-gated channel, not \(\text{K}^+\) exit, ligand binding, or a chloride flux. (Choice A) is wrong because voltage-gated \(\text{K}^+\) channels mediate repolarization, where "Potassium ions reach equilibrium when the membrane voltage is below -70 mV," not vesicle release. (Choice B) is wrong because ligand-gated channels sit on the postsynaptic membrane, where transmitter "binds to ligand-gated ion channels in the postsynaptic membrane," and they respond to neurotransmitter rather than to the arriving voltage change. (Choice C) is wrong because mechanically gated channels open "in response to pressure, touch, stretching, and sound," and admitting \(\text{Cl}^-\) does not trigger release. (Choice D) is correct because the depolarized end bulb opens voltage-gated \(\text{Ca}^{2+}\) channels whose inward \(\text{Ca}^{2+}\) current drives exocytosis. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling which specific channel type and ion couple terminal depolarization to neurotransmitter release.' WHERE id = 'db831b8c-b76e-4123-ab04-7b7dd226b553';
UPDATE questions SET question_text = 'An action potential reaches a presynaptic axon terminal and voltage-gated \(\text{Ca}^{2+}\) channels open, so \(\text{Ca}^{2+}\) rushes into the synaptic end bulb. A neurophysiologist asks a student to predict the very next molecular event the incoming \(\text{Ca}^{2+}\) produces inside the terminal that leads to neurotransmitter release.', options = '[{"text":"\\(\\text{Ca}^{2+}\\) associates with proteins on the outer surface of the neurotransmitter vesicles and facilitates their fusion with the presynaptic membrane, releasing transmitter by exocytosis","label":"A"},{"text":"\\(\\text{Ca}^{2+}\\) binds receptor proteins on the postsynaptic membrane and opens their ion channels, depolarizing the target cell directly","label":"B"},{"text":"\\(\\text{Ca}^{2+}\\) is pumped back out across the presynaptic membrane, and that outward movement squeezes the vesicles into the synaptic cleft","label":"C"},{"text":"\\(\\text{Ca}^{2+}\\) opens voltage-gated \\(\\text{Na}^+\\) channels in the terminal so that incoming \\(\\text{Na}^+\\) drives the vesicles to fuse with the membrane","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is A because, once \(\text{Ca}^{2+}\) enters the synaptic end bulb, it acts directly on the vesicles: it associates with proteins on the outer surface of the neurotransmitter vesicles and facilitates their merging with the presynaptic membrane, releasing transmitter by exocytosis. The Anatomy & Physiology text states that "the \(\text{Ca}^{2+}\) ion associates with proteins in the outer surface of neurotransmitter vesicles" and that "the \(\text{Ca}^{2+}\) facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis." Biology 2e likewise notes that "Calcium ions entering the cell initiate a signaling cascade that causes small membrane-bound vesicles... to fuse with the presynaptic membrane," confirming that fusion is the immediate \(\text{Ca}^{2+}\)-driven event, not a postsynaptic or efflux event. (Choice A) is correct because \(\text{Ca}^{2+}\) binding to vesicle-surface proteins triggers vesicle fusion and exocytosis. (Choice B) is wrong because binding receptors and opening their channels on the postsynaptic membrane is the later step performed by the neurotransmitter after it crosses the cleft, not by \(\text{Ca}^{2+}\) in the terminal. (Choice C) is wrong because it is \(\text{Ca}^{2+}\) influx, not efflux, that triggers fusion; no outward pumping squeezes vesicles into the cleft. (Choice D) is wrong because depolarization opens the voltage-gated \(\text{Ca}^{2+}\) channels rather than the reverse, and \(\text{Na}^+\) entry does not trigger vesicle fusion. This is a Scientific Reasoning and Problem Solving question because it requires predicting, from the stated \(\text{Ca}^{2+}\) influx, the specific downstream molecular event that produces neurotransmitter release while rejecting plausible but misplaced alternatives.' WHERE id = 'befb2911-a6d1-47a4-b15f-3651669b271e';
UPDATE questions SET question_text = 'A marine toxin selectively and irreversibly blocks the voltage-gated \(\text{Ca}^{2+}\) channels in the presynaptic axon terminals of a cholinergic neuron, yet each action potential still propagates down the axon and depolarizes the terminal membrane normally. A physiologist records from the postsynaptic cell during repeated presynaptic firing and is asked to predict what happens at this synapse.', options = '[{"text":"Neurotransmitter is still released into the cleft, because the action potential''s depolarization of the terminal is by itself sufficient to drive vesicle fusion.","label":"A"},{"text":"No neurotransmitter is released into the cleft, because \\(\\text{Ca}^{2+}\\) cannot enter the terminal to trigger the fusion of synaptic vesicles with the presynaptic membrane.","label":"B"},{"text":"Neurotransmitter floods continuously into the cleft, because the blocked \\(\\text{Ca}^{2+}\\) channels lock the synaptic vesicles permanently fused to the presynaptic membrane.","label":"C"},{"text":"Neurotransmitter is still released but cannot act, because the block also closes the ligand-gated receptor channels on the postsynaptic membrane.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is B because \(\text{Ca}^{2+}\) entry through the presynaptic voltage-gated \(\text{Ca}^{2+}\) channels is the obligatory trigger for vesicle fusion, so blocking those channels prevents neurotransmitter release even though the action potential still arrives. The text states that "When an action potential reaches the axon terminals, voltage-gated \(\text{Ca}^{2+}\) channels in the membrane of the synaptic end bulb open. The concentration of \(\text{Ca}^{2+}\) increases inside the end bulb... The \(\text{Ca}^{2+}\) facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis into the synaptic cleft" (A&P 2e). Likewise, Biology 2e notes that "voltage-gated \(\text{Ca}^{2+}\) channels open and allow \(\text{Ca}^{2+}\) to enter the cell. The calcium entry causes synaptic vesicles to fuse with the membrane and release neurotransmitter." If the \(\text{Ca}^{2+}\) channels are blocked, the depolarization arrives but no \(\text{Ca}^{2+}\) enters, vesicles do not fuse, and the cleft never receives transmitter. (Choice A) is wrong because the depolarization is only an upstream step; the text makes \(\text{Ca}^{2+}\) influx—not depolarization alone—the event that "facilitates the merging of the vesicle with the presynaptic membrane." (Choice B) is correct because with no \(\text{Ca}^{2+}\) entry there is no fusion and therefore no release into the synaptic cleft. (Choice C) reverses the causal relationship: blocking \(\text{Ca}^{2+}\) entry prevents fusion rather than locking vesicles permanently fused and releasing transmitter continuously. (Choice D) is wrong because the toxin acts only on presynaptic \(\text{Ca}^{2+}\) channels; the postsynaptic ligand-gated receptors are a separate component and, in any case, no transmitter is released for them to bind. This is a Scientific Reasoning and Problem Solving question because it requires predicting the downstream consequence of a specific molecular perturbation by reasoning through the \(\text{Ca}^{2+}\)-dependent fusion step of the release mechanism.' WHERE id = '7c432d8c-b87b-4dcc-bb53-236aea938d64';
UPDATE questions SET question_text = 'A presynaptic neuron is bathed in a saline solution from which all extracellular \(\text{Ca}^{2+}\) has been removed. When the axon is stimulated, intracellular recordings confirm that the presynaptic action potential reaches the terminal with its normal amplitude and time course, yet no postsynaptic response is detected. The experimenter wants to localize the broken step in synaptic transmission.', options = '[{"text":"The defect is upstream: without \\(\\text{Ca}^{2+}\\), the action potential can no longer reach or depolarize the axon terminal, so the terminal never becomes active.","label":"A"},{"text":"The defect is postsynaptic: removing \\(\\text{Ca}^{2+}\\) leaves release intact but prevents neurotransmitter from binding its receptors across the cleft.","label":"B"},{"text":"The defect is in removal: without \\(\\text{Ca}^{2+}\\), the released transmitter is not cleared, so it lingers and desensitizes the receptors, silencing the response.","label":"C"},{"text":"The defect is in release: with no \\(\\text{Ca}^{2+}\\) to enter the open channels, synaptic vesicles fail to fuse, so no neurotransmitter is exocytosed into the cleft.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is D because the action potential and its \(\text{Na}^+\)-driven depolarization still occur, but with no extracellular \(\text{Ca}^{2+}\) available to enter when the voltage-gated \(\text{Ca}^{2+}\) channels open, the \(\text{Ca}^{2+}\)-triggered fusion of synaptic vesicles cannot happen, so no transmitter is exocytosed. The text states that when an action potential reaches the terminal, voltage-gated \(\text{Ca}^{2+}\) channels open and ''Calcium ions entering the cell initiate a signaling cascade that causes... synaptic vesicles... to fuse with the presynaptic membrane'' (Biology 2e), and that ''The \(\text{Ca}^{2+}\) facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis'' (A&P 2e). Because the stem fixes the presynaptic spike as normal but the postsynaptic response as absent, the only step that depends on the missing variable—extracellular \(\text{Ca}^{2+}\) influx—is vesicle fusion and release, pinpointing that as the break. (Choice A) is wrong because action potential conduction into the terminal depends on voltage-gated \(\text{Na}^+\) channels, not on extracellular \(\text{Ca}^{2+}\), and the stem explicitly reports the presynaptic spike is unchanged. (Choice B) is wrong because neurotransmitter-receptor binding is a key-and-lock event across the cleft that does not require extracellular \(\text{Ca}^{2+}\), and here the block is presynaptic, before any transmitter is released. (Choice C) is wrong because clearance by degradation or reuptake is a later step that acts on already-released transmitter; the response is lost because nothing is released, not because nothing is cleared. (Choice D) is correct because removing the \(\text{Ca}^{2+}\) that must enter to trigger fusion abolishes exocytosis while leaving the upstream electrical signal intact. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental manipulation, holding the unchanged presynaptic action potential as a control, and reasoning from the absent postsynaptic response to localize the defect to the specific \(\text{Ca}^{2+}\)-dependent fusion step.' WHERE id = 'c806c158-0701-4277-90ce-229b1819cae8';
UPDATE questions SET question_text = 'A patient begins taking a selective serotonin reuptake inhibitor (SSRI), a drug that blocks the presynaptic transporter that normally pumps serotonin back into the serotonergic terminal. At a serotonergic synapse where reuptake is the only clearance route and no cleft enzyme degrades this transmitter, a researcher measures signaling at the postsynaptic receptors after the drug takes effect. Which prediction is correct?', options = '[{"text":"Postsynaptic signaling is prolonged and intensified relative to the untreated synapse.","label":"A"},{"text":"Postsynaptic signaling returns to its baseline level once the terminal reduces further serotonin release.","label":"B"},{"text":"Postsynaptic signaling falls sharply because the terminal is starved of serotonin to release.","label":"C"},{"text":"Postsynaptic signaling switches from excitatory to inhibitory as serotonin builds up in the cleft.","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses.'' Serotonin is a biogenic amine whose only route of removal from the synaptic cleft is reuptake: the textbook states that serotonin "is transported back into the presynaptic cell for repackaging" and lists "Reuptake by neurons" as the elimination mechanism for biogenic amines, with no cleft-degrading enzyme (Anatomy & Physiology 2e). Because a neurotransmitter''s effect persists only while it remains bound to its receptors, blocking the sole clearance transporter lets serotonin accumulate and keep re-binding. (Choice A) is correct: with reuptake blocked and no enzyme to substitute, serotonin lingers in the cleft and continues binding its receptors, so the postsynaptic response lasts longer and is stronger than at the untreated synapse. (Choice B) is incorrect: although serotonergic terminals do have autoreceptors, the immediate pharmacological effect of blocking clearance is a net rise in cleft serotonin; presynaptic feedback modulates but does not fully cancel the accumulation, so signaling does not simply return to baseline. (Choice C) is incorrect: it confuses clearance with release—reuptake recycles transmitter for later use, but vesicular release is a separate \(\text{Ca}^{2+}\)-triggered exocytosis step, and the drug acts fast enough that impaired recycling does not starve the terminal or reduce signaling. (Choice D) is incorrect: accumulating serotonin binds the same receptors more, prolonging and strengthening the existing response; the sign of the effect is set by the receptor type, so simply having more transmitter does not flip an excitatory synapse into an inhibitory one. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between a transmitter''s clearance route and its receptor-binding duration to predict the downstream effect of blocking that route.' WHERE id = 'ea28b186-88de-4b7c-acd2-b0151f88ca0c';
UPDATE questions SET question_text = 'An action potential travels down the axon of a somatic motor neuron and reaches the axon terminal at the neuromuscular junction of a skeletal muscle fiber. Which chemical messenger is most directly released into the synaptic cleft to bind receptors on the motor end-plate?', options = '[{"text":"Acetylcholine","label":"A"},{"text":"Acetylcholinesterase","label":"B"},{"text":"Calcium ions","label":"C"},{"text":"Norepinephrine","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the axon terminal of a somatic motor neuron releases acetylcholine into the synaptic cleft, where it binds receptors on the motor end-plate to begin excitation. The textbook states, "At the NMJ, the axon terminal releases a chemical messenger, or neurotransmitter, called acetylcholine (ACh). The ACh molecules diffuse across a minute space called the synaptic cleft and bind to ACh receptors located within the motor end-plate of the sarcolemma" (lines 17276-17278). The source also lists, for the NMJ, that "the neurotransmitter is acetylcholine" (line 22219). Binding opens a receptor channel that lets positively charged ions enter and depolarize the fiber, initiating excitation-contraction coupling. (Choice A) Acetylcholine is correct: it is the neurotransmitter packaged in vesicles in the presynaptic terminal and exocytosed into the cleft to act on the end-plate. (Choice B) Acetylcholinesterase is the enzyme that degrades ACh in the cleft so it "cannot rebind to a receptor and reopen its channel" (lines 17289-17291); it terminates the signal rather than being the released messenger. (Choice C) Calcium ions are the intracellular trigger inside the terminal — when the action potential arrives, "voltage-gated \(\text{Ca}^{2+}\) channels in the membrane of the synaptic end bulb open" and \(\text{Ca}^{2+}\) "facilitates the merging of the vesicle with the presynaptic membrane" (lines 22225-22228), so \(\text{Ca}^{2+}\) causes ACh release but is not itself the messenger crossing the cleft to the end-plate. (Choice D) Norepinephrine is a biogenic-amine transmitter of adrenergic synapses released into the blood and at autonomic sites (lines 22283-22290), not the transmitter at the somatic skeletal NMJ. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the somatic motor neuron releases acetylcholine at the neuromuscular junction to depolarize the motor end-plate.' WHERE id = '1952ae8e-26da-443e-9d67-f16693f198c3';
UPDATE questions SET question_text = 'A histologist comparing two skeletal muscle fibers finds that one is densely packed with mitochondria while the other contains very few. The mitochondria-rich fiber is most directly suited to which capacity?', options = '[{"text":"Sustaining ATP production through aerobic metabolism","label":"A"},{"text":"Generating ATP rapidly through anaerobic glycolysis","label":"B"},{"text":"Producing high tension through faster cross-bridge cycling","label":"C"},{"text":"Storing reserve \\(\\text{O}_2\\) within the sarcoplasm itself","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because aerobic metabolism occurs inside mitochondria, so a fiber packed with mitochondria is built to make ATP aerobically for sustained, fatigue-resistant contraction. The textbook states that oxidative fibers contain many more mitochondria than glycolytic fibers "because aerobic metabolism, which uses oxygen (\(\text{O}_2\)) in the metabolic pathway, occurs in the mitochondria" (lines 17821-17822). Slow oxidative fibers possess a large number of mitochondria and can contract for longer periods because of the large amount of ATP they produce aerobically, allowing them to sustain activity without fatiguing (lines 17822-17829). This is exactly why abundant mitochondria mark a fiber for endurance rather than for brief, powerful bursts. (Choice A) is correct: the high mitochondrial density reflects reliance on oxidative (aerobic) ATP production, which yields more ATP per cycle and resists fatigue (lines 17813-17819, 17821-17822). (Choice B) reverses the relationship, because anaerobic glycolysis is the pathway of fast glycolytic fibers, which "do not possess substantial numbers of mitochondria"; glycolysis proceeds in the cytoplasm, not the mitochondria (lines 17845-17847). (Choice C) names an adjacent property that is unrelated to mitochondria, since contraction speed and rapid cross-bridge cycling depend on how quickly myosin ATPase hydrolyzes ATP, with fast fibers hydrolyzing ATP about twice as quickly as slow fibers (lines 17809-17811). (Choice D) confuses organelles, because intracellular \(\text{O}_2\) storage is the role of myoglobin held in the sarcoplasm, not of mitochondria, which consume \(\text{O}_2\) rather than store it (lines 17826-17827, 17872-17873). This is a Knowledge of Scientific Concepts and Principles question because you must recall that mitochondria are the site of aerobic (oxidative) ATP production and link their abundance to sustained, fatigue-resistant contraction.' WHERE id = 'ae31dafd-31b4-4432-afc1-f840e6842654';
UPDATE questions SET question_text = 'A geneticist crosses a true-breeding plant bearing crimson petals to a true-breeding plant bearing ivory petals and obtains a uniform rose F1. When one F1 individual is crossed back to the ivory parent, the offspring distribute as shown.

| Backcross offspring | Petal phenotype | Fraction |
|---|---|---|
| Group 1 | rose (between crimson and ivory) | 1/2 |
| Group 2 | ivory | 1/2 |

The appearance of the rose phenotype in half the offspring most strongly indicates which pattern of inheritance?', options = '[{"text":"Complete dominance of crimson over ivory","label":"A"},{"text":"Incomplete dominance between the two petal alleles","label":"B"},{"text":"Codominance of the crimson and ivory alleles","label":"C"},{"text":"Multiple alleles segregating at the petal locus","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because the heterozygous offspring display a single blended phenotype (rose) that lies between the two parental phenotypes, which defines incomplete dominance. In the backcross \(C^R C^I \times C^I C^I\), half the offspring are heterozygous \(C^R C^I\) and half are homozygous \(C^I C^I\); the heterozygotes show rose rather than crimson, demonstrating that neither allele is fully dominant. OpenStax states that incomplete dominance denotes "the expression of two contrasting alleles such that the individual displays an intermediate phenotype," exactly as the snapdragon heterozygote \(C^R C^W\) produces pink flowers between red and white. The intermediate (rose) appearance of the heterozygote, not a parental or doubled phenotype, is the signature being tested here. (Choice A) Complete dominance is incorrect because the heterozygote would then resemble the crimson parent, not show an intermediate rose color; OpenStax describes dominant traits as fully expressed, so no blending would appear. (Choice B) is correct: the heterozygote''s intermediate phenotype is the defining feature of incomplete dominance, in which the heterozygote phenotype is intermediate between the two homozygous phenotypes. (Choice C) Codominance is incorrect because codominance requires that "both alleles for the same characteristic are simultaneously expressed in the heterozygote"—the heterozygote would show distinct crimson and ivory regions together, not a single blended rose, as in the MN blood groups where both M and N antigens appear. (Choice D) Multiple alleles is incorrect because that concept describes more than two alleles existing for a gene at the population level, which the data on a single two-allele cross neither shows nor requires. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of dominance patterns to a cross outcome and infer the underlying mechanism from the offspring phenotypes.' WHERE id = '98e461a0-e51b-4717-9dc9-48efa68701dc';
UPDATE questions SET question_text = 'A chemist compares the electron-attracting tendency of chlorine, located one period below and one group to the right of oxygen, against that of oxygen itself. Although chlorine sits farther to the right along its period, the comparison must reconcile two opposing periodic influences. Which element holds the greater electronegativity, and what governs the outcome?', options = '[{"text":"\\(\\text{Cl}\\), because its larger nuclear charge of \\(Z = 17\\) outweighs any effect of period placement","label":"A"},{"text":"\\(\\text{Cl}\\), because moving rightward across a period always raises electronegativity more than moving up a group raises it","label":"B"},{"text":"\\(\\text{O}\\) and \\(\\text{Cl}\\) are equal, because the rightward shift and the downward shift cancel one another","label":"C"},{"text":"\\(\\text{O}\\), because the shorter distance from the nucleus to the valence shell in period 2 outweighs the rightward gain chlorine has in period 3","label":"D"}]'::jsonb, explanation = 'This item targets periodic trends, specifically how the across-period and down-group components of electronegativity combine when they oppose each other. Electronegativity rises left-to-right across a period and falls top-to-bottom down a group. Oxygen sits in period 2 and chlorine one period lower and one group to the right, so the two trends conflict. The dominant factor is the proximity of the bonding electrons to the nucleus: oxygen''s valence shell (\(n = 2\)) lies much closer to its nucleus than chlorine''s (\(n = 3\)), giving the oxygen nucleus a stronger grip on shared electrons. The smaller radius wins, so oxygen (Pauling \(\approx 3.44\)) exceeds chlorine (Pauling \(\approx 3.16\)), making D correct. (Choice A) A larger total nuclear charge does not by itself determine electronegativity, because added inner electrons shield the valence shell; the effective nuclear charge felt by the bonding electrons together with their distance, not the raw \(Z = 17\), sets the trend. (Choice B) The across-period increase does not universally dominate the down-group decrease; here the upward (smaller-period) advantage of oxygen overrides chlorine''s rightward position, so the rule stated is false. (Choice C) The two influences do not cancel to equality; measured values place oxygen distinctly above chlorine, so no offsetting balance occurs. Skill 1.' WHERE id = 'd99d49f6-ee24-4460-8656-6fb88d4b56d0';
UPDATE questions SET question_text = 'A neutral atom of an unknown isotope contains 16 neutrons and a total of 15 electrons distributed across its orbitals. Which species does this atom most likely represent?', options = '[{"text":"A neutral atom of sulfur, \\(\\text{S}\\)","label":"A"},{"text":"An isotope of silicon, \\(^{31}\\text{Si}\\)","label":"B"},{"text":"A neutral atom of phosphorus, \\(\\text{P}\\)","label":"C"},{"text":"A sulfide ion, \\(\\text{S}^{2-}\\)","label":"D"}]'::jsonb, explanation = 'This item tests element identity from subatomic particle counts. In a neutral atom the number of protons equals the number of electrons, so 15 electrons fix \(Z = 15\); the element with \(Z = 15\) is phosphorus, and the mass number is \(15 + 16 = 31\), giving \(^{31}\text{P}\). The atomic number, not the neutron count or mass number, is the sole determinant of which element an atom is. (Choice A) Sulfur has \(Z = 16\), requiring 16 protons and thus 16 electrons in the neutral state; the 16 neutrons are matched to proton count rather than being used to read off identity, since neutron number defines the isotope, not the element. (Choice B) Silicon has \(Z = 14\); the mass number 31 coincidentally matches \(15 + 16\), but pairing that mass number with the wrong proton count assigns an element whose 14 protons cannot host 15 electrons in a neutral atom. (Choice D) Adding two electrons to reach a closed-shell count of 16 invokes the sulfide configuration, but a species with 15 protons carrying a \(2-\) charge would have 17 electrons, and a neutral 15-electron atom cannot be an anion of a different element. Skill 1: this question requires identifying and recalling that atomic number determines elemental identity.' WHERE id = 'c6ace4a1-5f28-493b-8f9e-9fe23b036b47';
UPDATE questions SET question_text = 'A biochemist measures the steady-state kinetics of four enzymes acting on their physiological substrates and obtains the following values: crotonase, \(k_{cat}=5.7\times10^{3}\,\mathrm{s^{-1}}\) and \(K_m=2\times10^{-5}\,\mathrm{M}\); catalase, \(k_{cat}=4\times10^{7}\,\mathrm{s^{-1}}\) and \(K_m=1.1\,\mathrm{M}\); carbonic anhydrase, \(k_{cat}=1\times10^{6}\,\mathrm{s^{-1}}\) and \(K_m=1.2\times10^{-2}\,\mathrm{M}\); acetylcholinesterase, \(k_{cat}=1.4\times10^{4}\,\mathrm{s^{-1}}\) and \(K_m=9\times10^{-5}\,\mathrm{M}\). At substrate concentrations well below each enzyme''s \(K_m\), which enzyme most likely converts free substrate to product most efficiently?', options = '[{"text":"Crotonase","label":"A"},{"text":"Catalase","label":"B"},{"text":"Carbonic anhydrase","label":"C"},{"text":"Acetylcholinesterase","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because catalytic efficiency at low substrate concentration is governed by the specificity constant \(k_{cat}/K_m\), not by \(k_{cat}\) alone, and crotonase has the largest \(k_{cat}/K_m\) of the four enzymes. The textbook states that "Under condition when \([S] \ll K_\text{M}\), the Michaelis-Menten equation becomes \(v_0 = (k_{cat}/K_\text{M})[E_0][S]\). This really describes a biomolecular rate constant \((k_{cat}/K_\text{M})\), with units of \(\text{M}^{-1}\text{s}^{-1}\), for the conversion of free substrate to product" (LibreTexts 27368-27369), and it identifies \(k_{cat}/K_m\) as the parameter that "describes how well an enzyme can differentiate between two different and competing substrates" (LibreTexts 27371-27377). Dividing \(k_{cat}\) by \(K_m\) gives crotonase \(\approx2.9\times10^{8}\), acetylcholinesterase \(\approx1.6\times10^{8}\), carbonic anhydrase \(\approx8.3\times10^{7}\), and catalase \(\approx3.6\times10^{7}\,\mathrm{M^{-1}s^{-1}}\), so crotonase is the most efficient at sub-\(K_m\) substrate. (Choice A) is correct: crotonase has the highest \(k_{cat}/K_m\) (\(\approx2.9\times10^{8}\,\mathrm{M^{-1}s^{-1}}\)), so under the low-[S] regime where \(v_0=(k_{cat}/K_m)[E_0][S]\) it converts free substrate to product fastest per unit enzyme and substrate (LibreTexts 27368-27369). (Choice B) is wrong: catalase has by far the largest \(k_{cat}\) (\(4\times10^{7}\,\mathrm{s^{-1}}\)), but its very large \(K_m\) (1.1 M) gives the smallest \(k_{cat}/K_m\) (\(\approx3.6\times10^{7}\,\mathrm{M^{-1}s^{-1}}\)); turnover number measures only "how many bound substrate molecules ''turnover'' or form product in 1 second" and applies to the saturated regime, not low-[S] efficiency (LibreTexts 27366-27367). (Choice C) is wrong: carbonic anhydrase also has a high \(k_{cat}\) (\(10^{6}\,\mathrm{s^{-1}}\)) but a large \(K_m\) (\(1.2\times10^{-2}\,\mathrm{M}\)), yielding \(k_{cat}/K_m\approx8.3\times10^{7}\,\mathrm{M^{-1}s^{-1}}\), which is below crotonase''s, so a high turnover number alone does not make it the most efficient at sub-\(K_m\) substrate (LibreTexts 27368-27369). (Choice D) is wrong: acetylcholinesterase has a respectable \(k_{cat}/K_m\approx1.6\times10^{8}\,\mathrm{M^{-1}s^{-1}}\), the second highest, but it is still smaller than crotonase''s \(\approx2.9\times10^{8}\), so it is not the most efficient under the conditions specified (LibreTexts 27368-27369). This is a Scientific Reasoning and Problem Solving question because you must apply the relationship \(v_0=(k_{cat}/K_m)[E_0][S]\) for the \([S] \ll K_m\) regime, compute and compare the specificity constant \(k_{cat}/K_m\) for each enzyme rather than ranking by \(k_{cat}\) alone, and recognize that the enzyme with the largest turnover number is not the most catalytically efficient at low substrate concentration.' WHERE id = '8e924d07-13a9-4373-908f-20b5a5d2ce7b';
UPDATE questions SET question_text = 'Constitutional (structural) isomers share a molecular formula but differ in the connectivity of their atoms, whereas stereoisomers share both formula and connectivity and conformational isomers interconvert by rotation about single bonds. Which of the following pairs of compounds is best classified as a pair of constitutional isomers?', options = '[{"text":"cis-2-butene and trans-2-butene","label":"A"},{"text":"The anti and gauche rotamers of butane about the C2-C3 bond","label":"B"},{"text":"(R)-2-bromobutane and (S)-2-bromobutane","label":"C"},{"text":"1-propanol and 2-propanol","label":"D"}]'::jsonb, explanation = 'This is an Organic Chemistry question that falls under the content category ''Nature of molecules and intermolecular interactions''. The answer to this question is D because 1-propanol and 2-propanol share the molecular formula \(\text{C}_3\text{H}_8\text{O}\) yet differ in how their atoms are connected: in 1-propanol the hydroxyl is bonded to a terminal carbon (\(\text{CH}_3\text{CH}_2\text{CH}_2\text{OH}\)), while in 2-propanol it is bonded to the central carbon (\(\text{CH}_3\text{CH(OH)CH}_3\)). Because the bonding sequence itself differs, the pair are constitutional (structural) isomers, not stereoisomers or conformers. Constitutional isomers are defined by identical formula but distinct connectivity, which is precisely what distinguishes them from stereoisomers (same connectivity, different spatial arrangement) and conformational isomers (same molecule sampled at different rotations about single bonds). (Choice A) cis-2-butene and trans-2-butene have identical connectivity (\(\text{CH}_3\text{CH}{=}\text{CHCH}_3\)) and differ only in the fixed spatial arrangement of groups about the restricted C=C double bond, making them geometric stereoisomers rather than constitutional isomers. (Choice B) The anti and gauche forms of butane are the same molecule with the same connectivity, interconverting freely by rotation about the C2-C3 single bond; they are conformational isomers (rotamers), not constitutional isomers. (Choice C) (R)- and (S)-2-bromobutane have identical connectivity and are nonsuperimposable mirror images, so they are enantiomers, a subtype of stereoisomer, not constitutional isomers. Skill 2: Scientific Reasoning and Problem-Solving.' WHERE id = 'a9a81ab6-c35e-4925-8f24-e334df902227';
UPDATE questions SET question_text = 'A pharmacologist applies a compound to a resting neuron (\(V_\text{m}\) ~-70 mV) that selectively increases the number of open \(\text{K}^+\) leak channels in its membrane, while leaving \(\text{Na}^+\) leak channels, the \(\text{Na}^+\)/\(\text{K}^+\) pump, and all voltage-gated channels untouched. Given that the \(\text{K}^+\) equilibrium potential is ~-90 mV and the \(\text{Na}^+\) equilibrium potential is ~+60 mV, the student is asked to predict how \(V_\text{m}\) will change and to justify why the resting value sat where it did.', options = '[{"text":"\\(V_\\text{m}\\) hyperpolarizes toward ~-90 mV, because the resting membrane is far more permeable to \\(\\text{K}^+\\) than to \\(\\text{Na}^+\\), so adding \\(\\text{K}^+\\) leak channels pulls \\(V_\\text{m}\\) even closer to \\(E_\\text{K}\\).","label":"A"},{"text":"\\(V_\\text{m}\\) depolarizes toward ~0 mV, because \\(\\text{K}^+\\) has the larger concentration gradient, so adding \\(\\text{K}^+\\) leak channels lets more \\(\\text{K}^+\\) enter and drives \\(V_\\text{m}\\) toward 0 mV.","label":"B"},{"text":"\\(V_\\text{m}\\) stays unchanged near -70 mV, because \\(\\text{Na}^+\\) and \\(\\text{K}^+\\) are equally permeable at rest, so adding \\(\\text{K}^+\\) leak channels leaves the balance of leak currents unaffected.","label":"C"},{"text":"\\(V_\\text{m}\\) depolarizes toward ~+60 mV, because \\(\\text{Na}^+\\) leak dominates the resting membrane, so adding \\(\\text{K}^+\\) leak channels pushes \\(V_\\text{m}\\) toward \\(E_\\text{Na}\\).","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''The Action Potential''. The answer is A because the resting membrane potential sits near the \(\text{K}^+\) equilibrium potential precisely because the membrane is far more permeable to \(\text{K}^+\) than to \(\text{Na}^+\), so increasing \(\text{K}^+\) permeability drives \(V_\text{m}\) even closer to \(E_\text{K}\). OpenStax Biology 2e states that "the negative charge within the cell is created by the cell membrane being more permeable to potassium ion movement than sodium ion movement" and that "the neurons have far more potassium leakage channels than sodium leakage channels," which is why "the difference in the number of positively charged potassium ions (\(\text{K}^+\)) inside and outside the cell dominates the resting membrane potential." Because \(V_\text{m}\) is dominated by the most permeant ion, resting \(V_\text{m}\) (~-70 mV) lies close to \(E_\text{K}\) (~-90 mV) rather than \(E_\text{Na}\) (~+60 mV); adding still more open \(\text{K}^+\) channels makes the membrane even more \(\text{K}^+\)-selective and pulls \(V_\text{m}\) toward \(E_\text{K}\), hyperpolarizing the cell, consistent with OpenStax Anatomy & Physiology 2e noting that "Potassium ions reach equilibrium when the membrane voltage is below -70 mV," producing hyperpolarization. (Choice A) is correct: greater \(\text{K}^+\) permeability anchors \(V_\text{m}\) near \(E_\text{K}\), and more \(\text{K}^+\) leak channels hyperpolarize toward ~-90 mV. (Choice B) is wrong because it correctly places \(V_\text{m}\) near \(E_\text{K}\) via the \(\text{K}^+\) gradient but predicts the opposite direction; more open \(\text{K}^+\) channels move \(V_\text{m}\) toward \(E_\text{K}\) (~-90 mV), not toward 0 mV, and the driving force on \(\text{K}^+\) is net outward, not inward. (Choice C) is wrong because the membrane is not equally permeable to \(\text{Na}^+\) and \(\text{K}^+\) at rest; the text states there are far more \(\text{K}^+\) than \(\text{Na}^+\) leak channels, so adding \(\text{K}^+\) channels does change the leak balance. (Choice D) is wrong because it reverses which ion the resting membrane is most permeable to; \(\text{K}^+\) leak dominates, not \(\text{Na}^+\) leak, so \(V_\text{m}\) sits near \(E_\text{K}\) and added \(\text{K}^+\) channels cannot push it toward \(E_\text{Na}\). This is a Scientific Reasoning and Problem Solving question because it requires predicting the direction of a membrane-potential change from a manipulation of ion permeability and justifying it against the equilibrium potentials, rather than recalling a stated fact.' WHERE id = '2dc7a27d-6c17-4d1a-bb05-f304e0689110';
UPDATE questions SET question_text = 'A neurologist studies a patient whose myelin has been stripped from a long axon segment, forcing the impulse to travel by continuous conduction along the now-bare membrane instead of jumping between nodes of Ranvier. Compared with the same axon when it was myelinated and conducting saltatorily, the neurologist predicts that propagating one impulse along the demyelinated stretch will demand more of which cellular resource?', options = '[{"text":"Less ATP, because losing the myelin sheath removes a structure the neuron had to metabolically maintain","label":"A"},{"text":"More ATP, because the \\(\\text{Na}^+\\)/\\(\\text{K}^+\\) pump must now restore gradients along the entire membrane rather than only at the nodes","label":"B"},{"text":"An unchanged amount of ATP, because each action potential is all-or-none and so costs a fixed amount of energy","label":"C"},{"text":"More \\(\\text{Ca}^{2+}\\) extrusion, because conduction along the bare membrane drives extra \\(\\text{Ca}^{2+}\\) influx the cell must pump out","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses''. The answer is B because saltatory conduction''s energy savings come from confining voltage-gated channels to the nodes of Ranvier, so abolishing that arrangement forces the impulse to be regenerated everywhere and admits \(\text{Na}^+\) along the whole membrane, all of which the \(\text{Na}^+\)/\(\text{K}^+\) pump must then extrude. The text states that "Nodes of Ranvier also save energy for the neuron since the channels only need to be present at the nodes and not along the entire axon" (Biology 2e, 46045-46046), and continuous conduction is described as a state in which "there are always voltage-gated \(\text{Na}^+\) channels opening, and more and more \(\text{Na}^+\) is rushing into the cell" (A&P 2e, 22062-22063). Because the cell must pump out every \(\text{Na}^+\) that entered (and pump \(\text{K}^+\) back in) to restore the gradients, regenerating the impulse at every point rather than only at scattered nodes raises the total ion-pumping (ATP) burden over the whole demyelinated length. (Choice A) is wrong and reverses the relationship: the energy saving comes from restricting channel activity to the nodes (46045), so forcing continuous regeneration increases ATP cost rather than lowering it. (Choice B) is correct because continuous conduction admits \(\text{Na}^+\) across the entire membrane, and restoring those gradients along the whole length requires more pumping than restoring them only at nodes (46044-46046). (Choice C) is a partial truth: each action potential is indeed all-or-none in amplitude, but regenerating it at every point along the membrane lets far more total \(\text{Na}^+\) enter to be pumped back out, so the integrated energy cost is not fixed (46044-46046). (Choice D) is an adjacent fact that misattributes the ion: nodal and continuous regeneration of the impulse run through voltage-gated \(\text{Na}^+\) and \(\text{K}^+\) channels (46040-46041), not axonal \(\text{Ca}^{2+}\) entry. This is a Scientific Reasoning and Problem Solving question because it requires chaining the channel-distribution principle to a metabolic prediction about an experimentally altered (demyelinated) axon rather than recalling a single stated fact.' WHERE id = '52dcc2e1-a255-444a-ba1d-38dc1e20f2df';
UPDATE questions SET question_text = 'In the Haber process \(\text{N}_2 + 3\,\text{H}_2 \rightarrow 2\,\text{NH}_3\), a reaction vessel is charged with excess \(\text{N}_2\) and \(4.0\,\text{mol}\) of \(\text{H}_2\) that reacts completely. How many moles of \(\text{NH}_3\) form?', options = '[{"text":"\\(1.33\\,\\text{mol}\\)","label":"A"},{"text":"\\(4.0\\,\\text{mol}\\)","label":"B"},{"text":"\\(2.67\\,\\text{mol}\\)","label":"C"},{"text":"\\(6.0\\,\\text{mol}\\)","label":"D"}]'::jsonb, explanation = 'This is a General Chemistry question that falls under the content category ''Stoichiometry (GC)''. The answer to this question is C because the balanced equation fixes a mole ratio of \(3\,\text{mol}\,\text{H}_2 : 2\,\text{mol}\,\text{NH}_3\), and that ratio is the bridge from the amount consumed to the amount produced. With \(\text{N}_2\) in excess, \(\text{H}_2\) is the limiting reactant, and all \(4.0\,\text{mol}\) is consumed: \(4.0\,\text{mol}\,\text{H}_2 \times \dfrac{2\,\text{mol}\,\text{NH}_3}{3\,\text{mol}\,\text{H}_2} = 2.67\,\text{mol}\,\text{NH}_3\). (Choice A) \(1.33\,\text{mol}\) results from multiplying by \(\dfrac{1}{3}\) (the \(\text{N}_2\!:\!\text{H}_2\) sub-bridge) instead of by \(\dfrac{2}{3}\), dropping the \(\text{NH}_3\) coefficient of 2. (Choice B) \(4.0\,\text{mol}\) assumes a 1:1 ratio between \(\text{H}_2\) and \(\text{NH}_3\), ignoring the balancing coefficients entirely. (Choice D) \(6.0\,\text{mol}\) comes from inverting the ratio and multiplying by \(\dfrac{3}{2}\) instead of \(\dfrac{2}{3}\). Skill 2' WHERE id = '6f67fe15-ac51-4c3d-a49b-04776de1fc4e';
UPDATE questions SET question_text = 'A researcher tags an enzyme of the citric acid cycle in a respiring liver cell and tracks where it carries out its reaction. The reaction this enzyme catalyzes is most directly localized to which mitochondrial compartment?', options = '[{"text":"The inner mitochondrial membrane, where the cristae folds reside","label":"A"},{"text":"The mitochondrial matrix, the space enclosed by the inner membrane","label":"B"},{"text":"The intermembrane space, between the outer and inner membranes","label":"C"},{"text":"The outer mitochondrial membrane, which bounds the organelle","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Cell and Tissue Structure (BIO)''. The answer is B because the citric acid cycle, including its enzymes, takes place in the mitochondrial matrix, the space enclosed by the inner membrane. The mitochondrion is a double-membrane organelle whose inner membrane is folded into cristae; the space enclosed by that inner membrane is the matrix, and the space between the two membranes is the intermembrane space (lines 5485-5495). The textbook states that "the citric acid cycle takes place in the matrix of mitochondria" and that "almost all of the enzymes of the citric acid cycle are soluble" within that compartment (lines 9389-9390). This is functionally separate from the inner membrane, where ATP synthesis and the proton gradient of the electron transport chain operate (line 5495). (Choice B) Correct: the soluble citric-acid-cycle enzymes reside in and act within the matrix, the compartment the inner membrane encloses; the lone membrane-bound exception, succinate dehydrogenase, does not change the cycle''s matrix localization. (Choice A) Incorrect: the inner membrane and its cristae host the electron transport chain and ATP synthase that build and use the proton gradient, not the soluble cycle reactions, so this confuses the membrane-bound oxidative phosphorylation machinery with the matrix-localized cycle. (Choice C) Incorrect: the intermembrane space is the reservoir into which protons \(\left(\text{H}^+\right)\) are pumped to form the gradient, not a catalytic compartment for the cycle''s soluble enzymes. (Choice D) Incorrect: the outer membrane merely bounds the organelle and has no role in housing citric-acid-cycle reactions, which require the enclosed matrix interior. This is a Knowledge of Scientific Concepts and Principles question because you must recall the internal organization of the mitochondrion and which sub-process of aerobic respiration each compartment carries out.' WHERE id = '5fe12304-44f4-4a4f-9e71-6e83191fd9d0';
UPDATE questions SET question_text = 'When formic acid and cyanide ion are combined in aqueous solution, the proton-transfer reaction \(\text{HCOOH} + \text{CN}^- \rightarrow \text{HCOO}^- + \text{HCN}\) takes place, and monitoring of the mixture shows formate \((\text{HCOO}^-)\) and \(\text{HCN}\) steadily accumulating. Which assignment of the Brønsted–Lowry acid and the Brønsted–Lowry base among the two reactants is consistent with this observed proton transfer?', options = '[{"text":"\\(\\text{HCOOH}\\) is the base, because its more electronegative oxygen makes it the proton acceptor, and \\(\\text{CN}^-\\) is the acid that supplies the proton.","label":"A"},{"text":"\\(\\text{CN}^-\\) is the acid, donating a proton to become \\(\\text{HCN}\\), and \\(\\text{HCOOH}\\) is the base, accepting that proton to become \\(\\text{HCOO}^-\\).","label":"B"},{"text":"\\(\\text{CN}^-\\) is the acid, because it ends up bearing the transferred proton as \\(\\text{HCN}\\), and \\(\\text{HCOOH}\\) is the base it took the proton from.","label":"C"},{"text":"\\(\\text{HCOOH}\\) is the acid, donating a proton to become \\(\\text{HCOO}^-\\), and \\(\\text{CN}^-\\) is the base, accepting that proton to become \\(\\text{HCN}\\).","label":"D"}]'::jsonb, explanation = 'This is a General Chemistry question that falls under the content category ''Acid-Base Equilibria (GC, BC)''. The answer to this question is D because a Brønsted–Lowry acid is the proton donor and a Brønsted–Lowry base is the proton acceptor in a single proton-transfer event. Tracking the atoms across the arrow shows that \(\text{HCOOH}\) loses its acidic proton to become \(\text{HCOO}^-\); having donated a proton, \(\text{HCOOH}\) is therefore the acid. The \(\text{CN}^-\) ion gains that proton to become \(\text{HCN}\); having accepted a proton, \(\text{CN}^-\) is therefore the base. The accumulation of \(\text{HCOO}^-\) and \(\text{HCN}\) confirms this direction of transfer, with \(\text{HCOOH}/\text{HCOO}^-\) and \(\text{HCN}/\text{CN}^-\) forming the two conjugate pairs. (Choice A) This claims \(\text{HCOOH}\) is the base because oxygen is highly electronegative, but Brønsted–Lowry classification depends on whether a species donates or accepts a proton, not on the electronegativity of an atom it contains; \(\text{HCOOH}\) releases its proton and is the acid. (Choice B) This reverses the roles: it labels the proton acceptor \(\text{CN}^-\) as the donor and the proton donor \(\text{HCOOH}\) as the acceptor. The species that loses a proton is the acid and the species that gains one is the base, so this assignment inverts both definitions. (Choice C) This identifies \(\text{CN}^-\) as the acid by pointing to the product \(\text{HCN}\) that carries the proton, but the acid is defined by the act of donating a proton during the reaction, not by which species ends up holding the proton afterward; \(\text{CN}^-\) acquires the proton, so it is the base, not the acid. Skill 4' WHERE id = '3efcdeea-abc2-4f15-badf-9748a2ccd08d';
UPDATE questions SET question_text = 'A purified protein is monitored by UV spectroscopy as the solution pH is raised from 7 to 12. Near pH 10.5 the near-UV absorbance shifts (a new signal appears at \(295\ \text{nm}\)), and this change is fully reversible when the pH is lowered again. The researcher concludes that a single class of side chain is being titrated over this range. Absorbance measurements at \(280\ \text{nm}\) confirm the protein contains all three aromatic residues in significant amounts. Which residue is most likely responsible for the pH-dependent spectral shift observed near pH 10.5?', options = '[{"text":"Tyrosine","label":"A"},{"text":"Phenylalanine","label":"B"},{"text":"Tryptophan","label":"C"},{"text":"Lysine","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' To produce a reversible, pH-dependent change in near-UV absorbance around pH 10.5, a residue must satisfy two conditions at once: its side chain must ionize (gain or lose a proton) in that pH range, and that ionization must alter a group that absorbs UV light. The LibreTexts reference notes that at high pH ''the side-chain hydroxyl is deprotonated (\(\text{pK}_a = 10.5\)), with concomitant changes in \(A_{295}\),'' and that ''these changes can be used to follow the titration of the Tyr residues in a protein.'' Among the three aromatic residues, only tyrosine carries an ionizable group directly on its UV-absorbing ring. (Choice A) is correct: tyrosine''s phenolic side-chain hydroxyl deprotonates near pH 10.5, and because that hydroxyl sits directly on the aromatic ring, its loss of a proton changes the ring''s absorbance, generating the reversible \(295\ \text{nm}\) signal used to titrate Tyr residues. (Choice B) is incorrect: phenylalanine absorbs UV light, but its side chain is an unsubstituted benzyl group with no ionizable substituent, so raising the pH to 10.5 does not protonate or deprotonate it and produces no titration signal. (Choice C) is incorrect: tryptophan also absorbs UV strongly, but its indole nitrogen''s lone pair is delocalized into the aromatic ring and is not titratable in this range, so its absorbance does not shift with pH near 10.5. (Choice D) is incorrect: lysine''s \(\varepsilon\)-amino side chain does ionize near pH 10.5, so it is titrated in this range, but it is aliphatic and has no chromophore, so its deprotonation produces no change in near-UV absorbance. This is a Scientific Reasoning and Problem Solving question because you must apply the requirement that the same residue be both titratable near pH 10.5 and UV-absorbing, integrating side-chain \(\text{pK}_a\) with the spectroscopic observation rather than recalling a definition.' WHERE id = '8a8e9aaf-87c2-465e-9b21-90cf355c9f31';
UPDATE questions SET question_text = 'In each subunit of hemoglobin, a heme prosthetic group positions a central iron ion that picks up molecular oxygen in the lungs and releases it in respiring tissue. Which property of this iron center allows the same subunit to load and unload \(\text{O}_2\) repeatedly?', options = '[{"text":"It is covalently attached to a cysteine thiol","label":"A"},{"text":"It cycles between \\(\\text{Fe}^{2+}\\) and \\(\\text{Fe}^{3+}\\) states","label":"B"},{"text":"It forms hydrogen bonds with dioxygen","label":"C"},{"text":"It binds \\(\\text{O}_2\\) reversibly as ferrous \\(\\text{Fe}^{2+}\\)","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because the heme of hemoglobin holds a central ferrous \(\text{Fe}^{2+}\) ion that forms a coordinate covalent bond with dioxygen, and this binding is reversible: \(\text{O}_2\) is picked up where its concentration is high and released where it is low. The textbook states that ''Dioxygen binds to a heme \(\text{Fe}^{2+}\) transition metal through a coordinate covalent or dative bond'' and that ''the oxidation state of the \(\text{Fe}^{2+}\) ion does not change... Hence, the \(\text{Fe}^{2+}\) ion is a reversible carrier of dioxygen and not electrons.'' Because the iron stays in the +2 state and the bond can dissociate, the same subunit can load and unload \(\text{O}_2\) many times. (Choice A) is incorrect: the heme iron is held by coordinate covalent bonds to four pyrrole nitrogens and the proximal histidine, not by a covalent bond to a cysteine thiol; the textbook notes the proximal His ''serves as the 5th ligand to the heme \(\text{Fe}^{2+}\)'' and that the porphyrin ''has a nitrogen atom on each of the four pyrrole rings that form a coordinate covalent bond to \(\text{Fe}^{2+}\).'' (Choice B) is incorrect: cycling between \(\text{Fe}^{2+}\) and \(\text{Fe}^{3+}\) describes the heme iron of cytochrome c during electron transport, where ''the heme''s central ion alternately reduces and oxidizes during electron transfer''; in oxygen-carrying hemoglobin the \(\text{Fe}^{2+}\) oxidation state does not change. (Choice C) is incorrect: \(\text{O}_2\) is bound by a coordinate covalent (dative) bond in which the ligand donates both electrons to the iron, not by a hydrogen bond. (Choice D) is correct: the heme iron remains ferrous \(\text{Fe}^{2+}\) and serves as a reversible carrier of dioxygen, exactly the property that permits repeated loading and unloading. This is a Knowledge of Scientific Concepts and Principles question because you must recall the structure of the heme prosthetic group and the oxidation state and reversible binding behavior of its central iron.' WHERE id = '0f8ee3b7-814b-4eae-abd6-2cf6d9f79ee9';
UPDATE questions SET question_text = 'A student titrates a pure solution of leucine, a nonpolar amino acid whose side chain is an isobutyl group, from strongly acidic to strongly basic pH while recording the curve of pH versus added base. As she interprets the resulting curve, how many distinct buffering plateaus (regions where \(\text{pH} = \text{pK}_a\)) should she expect to observe?', options = '[{"text":"Two plateaus","label":"A"},{"text":"Three plateaus","label":"B"},{"text":"One plateau","label":"C"},{"text":"Four plateaus","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the number of buffering plateaus on a titration curve equals the number of ionizable groups, and leucine has exactly two: the \(\alpha\)-carboxyl (\(-\text{COOH}\), \(\text{pK}_a \approx 2\)) and the \(\alpha\)-amino (\(-\text{NH}_3^+\), \(\text{pK}_a \approx 9.6\)). The textbook states that ''all amino acids have an amine and carboxylic acid group, and some have an additional ionizable side chain. Each has its \(\text{pK}_a\) values... three general plateaus, each centered at the \(\text{pK}_a\) value of the ionizable group, can be seen in their titration curves'' (libretexts-biochemistry.txt, lines 3158-3161), and it explicitly treats glycine as having ''no ionizable side chain'' (line 5516). Leucine''s isobutyl side chain is a saturated hydrocarbon with no acidic or basic proton, so it contributes no plateau; the curve therefore shows only the two terminal-group plateaus, each centered where \(\text{pH} = \text{pK}_a\) (line 3151). (Choice A) is correct: two ionizable groups (\(\alpha\)-carboxyl and \(\alpha\)-amino) give two \(\text{pK}_a\) values and thus two buffering plateaus. (Choice B) is wrong because a third plateau would require a third ionizable group; three plateaus describe a triprotic amino acid with an ionizable side chain (e.g., Glu, Lys), not a nonpolar one like leucine. (Choice C) is wrong because it counts the molecule as if it had a single ionizable group, ignoring that the \(\alpha\)-amino group titrates separately from the \(\alpha\)-carboxyl. (Choice D) is wrong because it over-counts ionizable groups, treating the nonpolar isobutyl side chain (and an imagined extra group) as titratable when it has no ionizable proton. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that plateau count equals ionizable-group count to reason from leucine''s structure to the shape of its titration curve.' WHERE id = 'f2e6aeac-0708-4acc-bc3b-d8b419dc7352';
UPDATE questions SET question_text = 'An action potential arrives at a presynaptic axon terminal, and moments later the neurotransmitter-filled synaptic vesicles fuse with the presynaptic membrane and empty into the synaptic cleft. The event that most directly couples the arriving action potential to this vesicle fusion is the:', options = '[{"text":"efflux of \\(\\text{K}^+\\) out of the terminal through voltage-gated potassium channels, restoring the resting membrane potential","label":"A"},{"text":"influx of \\(\\text{Ca}^{2+}\\) into the terminal through voltage-gated calcium channels that open when the membrane depolarizes","label":"B"},{"text":"influx of \\(\\text{Na}^+\\) into the terminal through voltage-gated sodium channels that carried the depolarization down the axon","label":"C"},{"text":"influx of \\(\\text{Cl}^-\\) into the terminal through ligand-gated chloride channels, driving the membrane away from threshold","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Impulse Propagation & Synapses.'' Neurotransmitter release is not triggered directly by the depolarization itself but by a specific ion that enters the terminal when the depolarization arrives. OpenStax Anatomy & Physiology 2e states that "when an action potential reaches the axon terminals, voltage-gated \(\text{Ca}^{2+}\) channels in the membrane of the synaptic end bulb open," and that "the \(\text{Ca}^{2+}\) facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis into the ... synaptic cleft." Thus the depolarizing action potential opens voltage-gated \(\text{Ca}^{2+}\) channels, and the resulting rise in intracellular \(\text{Ca}^{2+}\) is the signal that binds vesicle proteins and drives fusion. (Choice A) is incorrect: \(\text{K}^+\) efflux through voltage-gated potassium channels repolarizes the membrane back toward rest, terminating the depolarization rather than triggering vesicle fusion. (Choice B) is correct: depolarization of the terminal opens voltage-gated \(\text{Ca}^{2+}\) channels, and the influx of \(\text{Ca}^{2+}\) is what directly causes the vesicles to fuse with the presynaptic membrane and release transmitter. (Choice C) is incorrect: \(\text{Na}^+\) influx through voltage-gated sodium channels propagates the action potential along the axon and depolarizes the terminal, but it is the calcium that enters afterward—not the sodium itself—that couples that depolarization to fusion. (Choice D) is incorrect: \(\text{Cl}^-\) entry is a hyperpolarizing/inhibitory event at postsynaptic membranes that moves the membrane away from threshold, and it neither opens in response to presynaptic depolarization here nor triggers release. This is a Knowledge of Scientific Concepts and Principles question because you must recall that presynaptic depolarization opens voltage-gated \(\text{Ca}^{2+}\) channels and that the \(\text{Ca}^{2+}\) influx is the specific trigger for synaptic vesicle fusion.' WHERE id = '7d1fe515-2d67-488c-b94c-d08216e46a2b';
UPDATE questions SET question_text = 'A sprinter runs an all-out 400 m race and then stops and stands still at the finish line. Her rate of oxygen consumption is recorded before, during, and after the race:

| Phase | \(\text{O}_2\) consumption |
|---|---|
| Standing at rest before the race | Baseline |
| During the 400 m sprint | Sharply elevated |
| First several minutes after she stops running | Still well above baseline, then slowly declining |

Although her muscles are no longer contracting after she stops, her oxygen consumption stays elevated for several minutes. Which process most directly accounts for this elevated post-exercise oxygen consumption?', options = '[{"text":"Oxygen is used to rebuild creatine phosphate stores and to reconvert accumulated lactic acid","label":"A"},{"text":"Contracting muscle fibers continue to consume oxygen to sustain aerobic ATP production","label":"B"},{"text":"Myoglobin releases its stored oxygen to resupply the working mitochondria","label":"C"},{"text":"Anaerobic glycolysis accelerates to replace the ATP spent during the sprint","label":"D"}]'::jsonb, explanation = 'This is a Biology question that falls under the content category ''Organ Systems.'' During an all-out sprint, much of the ATP is produced anaerobically, and the textbook defines the resulting oxygen debt as "the amount of oxygen needed to compensate for ATP produced without oxygen during muscle contraction"; this debt is repaid after exercise, which is why "oxygen intake is elevated, even after exercise has stopped." The task is to reason about why oxygen uptake stays high once contraction has ceased, not simply to name an energy source. (Choice A) is correct: the textbook states that after intense activity, oxygen is required to "restore ATP and creatine phosphate levels, convert lactic acid to pyruvic acid, and, in the liver, to convert lactic acid into glucose or glycogen," so the elevated recovery oxygen consumption reflects repaying this oxygen debt while the muscle is no longer contracting. (Choice B) is incorrect: this attributes the elevated oxygen use to ongoing contractile work, but the stem specifies the muscles have stopped contracting, so sustained aerobic ATP production to power contraction cannot be the cause. (Choice C) is incorrect: myoglobin is an oxygen reserve that releases stored \(\text{O}_2\) to support aerobic respiration during activity, so it would supply oxygen while she is running rather than drive extra oxygen intake after she stops. (Choice D) is incorrect: glycolysis is an anaerobic, "non-oxygen-dependent" process, so accelerating it would not consume the additional inhaled oxygen; in fact restoring ATP and clearing lactic acid during recovery is oxygen-dependent, which is the opposite of anaerobic glycolysis. This is a Scientific Reasoning and Problem Solving question because you must apply the concept of oxygen debt to explain why post-exercise oxygen consumption remains elevated after muscular contraction has ceased.' WHERE id = '2b8a8094-9302-4a9c-98dd-061c52c2c2cf';
UPDATE questions SET question_text = 'A biochemist titrates glutamate, an amino acid whose carboxylic acid side chain adds a third ionizable group. The three \(\text{p}K_\text{a}\) values are listed below.

| Ionizable group | \(\text{pK}_a\) |
|---|---|
| \(\alpha\text{-COOH}\) | 2.2 |
| side-chain \(\gamma\text{-COOH}\) | 4.2 |
| \(\alpha\text{-NH}_3^+\) | 9.7 |

As base is added, the molecule passes through a species that carries a net charge of zero (the zwitterion). What is the isoelectric point (\(\text{pI}\)) of glutamate?', options = '[{"text":"3.2","label":"A"},{"text":"5.4","label":"B"},{"text":"6.0","label":"C"},{"text":"7.0","label":"D"}]'::jsonb, explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The isoelectric point is the pH at which the molecule carries no net charge; for a molecule with more than two ionizable groups it is found not by averaging the extreme or all \(\text{p}K_\text{a}\) values, but by averaging the two \(\text{p}K_\text{a}\) values that flank the net-zero (zwitterionic) species. To locate that species you track the charge as pH rises: at very low pH glutamate is fully protonated with net charge \(+1\) (both carboxyls neutral, amino group \(+1\)); deprotonating the \(\alpha\text{-COOH}\) (\(\text{p}K_\text{a}\) 2.2) gives net \(0\); deprotonating the side-chain \(\gamma\text{-COOH}\) (\(\text{p}K_\text{a}\) 4.2) gives net \(-1\); and deprotonating the \(\alpha\text{-NH}_3^+\) (\(\text{p}K_\text{a}\) 9.7) gives net \(-2\). The zwitterion therefore sits between \(\text{p}K_\text{a}\) 2.2 and \(\text{p}K_\text{a}\) 4.2, so \(\text{pI} = (2.2 + 4.2)/2 = 3.2\). (Choice A) is correct: 3.2 averages the two lowest \(\text{p}K_\text{a}\) values, which are the ones flanking the net-zero form of an acidic amino acid. (Choice B) is incorrect: 5.4 comes from averaging all three \(\text{p}K_\text{a}\) values, \((2.2 + 4.2 + 9.7)/3\), but the pI is defined only by the two that bracket the neutral species. (Choice C) is incorrect: 6.0 comes from averaging the two extreme values, \((2.2 + 9.7)/2\), the correct method for a simple amino acid with no ionizable side chain but wrong here because it skips the acidic \(\gamma\)-carboxyl and lands on a pH where the molecule is net \(-1\). (Choice D) is incorrect: 7.0 comes from averaging the two highest values, \((4.2 + 9.7)/2\); those \(\text{p}K_\text{a}\) values flank the transition from \(-1\) to \(-2\), not the net-zero species, so they give the wrong pH. This is a Scientific Reasoning and Problem Solving question because you must apply the definition of the isoelectric point to a triprotic amino acid, track its net charge through each deprotonation, and identify the correct pair of \(\text{p}K_\text{a}\) values to average rather than defaulting to a memorized two-value formula.' WHERE id = '77c9dedc-f49d-4b12-9c6a-c9ef5b066faf';
UPDATE flashcards SET cloze_text = 'Zeff {{c1::increases}} from left to right across a period (more protons added with negligible new shielding) but stays roughly {{c2::constant}} down a group (each added shell provides new shielding that cancels the added nuclear charge).' WHERE id = 'f42093b3-4233-40ee-baef-b1992ee339c3';
UPDATE flashcards SET cloze_text = 'Atomic radius {{c1::decreases}} from left to right across a period (rising Zeff pulls the same outer shell tighter) and {{c2::increases}} from top to bottom in a group (each new period adds an electron shell at a larger principal quantum number).' WHERE id = '8f7d617e-ae05-4a2c-872d-811eb745bbe5';
UPDATE flashcards SET cloze_text = 'Ionization energy {{c1::increases}} from left to right across a period (rising Zeff binds the valence electron more tightly) and {{c2::decreases}} from top to bottom in a group (valence electron is farther from the nucleus and more shielded).' WHERE id = 'e948523f-2b46-496b-af2b-2ed14b2ddf1c';
UPDATE flashcards SET cloze_text = 'Simple machines do not create energy — they only redistribute it. For an ideal (frictionless) machine, the work done by the input equals the work done by the output: {{c1::Fin × din = Fout × dout}}. So a higher mechanical advantage always comes with a longer input-distance trade-off.' WHERE id = 'fe5aa4fe-9520-4906-af28-c9b12268e385';
UPDATE flashcards SET cloze_text = 'The {{c1::efficiency}} of a real machine is the ratio of its useful work output to the work input, usually expressed as a percentage: {{c2::Efficiency = (Wout / Win) × 100%}}. For an ideal frictionless machine, efficiency = 100%; real machines are always less.' WHERE id = '0d9846de-b7f2-4020-9825-f839f31b582b';
UPDATE flashcards SET cloze_text = 'Newton''s second law states that the net force on an object equals its mass times its acceleration: {{c1::Fnet = ma}}. Because F and a are both vectors, they always point in the {{c2::same direction}}.' WHERE id = '8224a844-7297-4649-9265-9b8d86a6a431';
UPDATE flashcards SET cloze_text = 'Newton''s third law: when object A exerts a force on object B, object B simultaneously exerts an equal-magnitude {{c1::opposite-direction}} force back on A — mathematically, {{c2::F(AB) = −F(BA)}}. These two forces act on {{c3::different objects}} and cannot cancel each other out.' WHERE id = 'e012ff69-e657-4649-a44b-1abff66e7cca';
UPDATE flashcards SET cloze_text = 'In any circular motion, the net inward force is called the {{c1::centripetal force}}. This is not a separate kind of force — it is whatever actual force (gravity, tension, normal, friction, electromagnetic) happens to be directed toward the center of the circle. Its magnitude is {{c2::Fc = mv²/r}}.' WHERE id = '4409b4f7-ed23-4b80-8ee0-00021ee2e1c6';
UPDATE flashcards SET cloze_text = 'The work-energy theorem (Wnet = ΔK) relates net work to {{c1::kinetic energy only}} — not potential, not total mechanical energy. By contrast, the broader energy-conservation principle (ΔE = Wnc when E = K + U) relates non-conservative work to {{c2::total mechanical}} energy.' WHERE id = 'b8069e98-a273-4f4b-90b7-ed4ffead0341';
UPDATE flashcards SET cloze_text = 'The Ca²⁺ influx triggers fusion of neurotransmitter-filled {{c1::vesicles}} with the presynaptic membrane, releasing the neurotransmitter into the cleft by {{c2::exocytosis}}.' WHERE id = '88eb0cb9-d106-4b5f-8853-9238cdeb4fa6';
UPDATE flashcards SET cloze_text = 'A {{c1::metabotropic}} receptor is a G-protein-coupled receptor: NT binding triggers a second-messenger cascade that alters cyclic {{c2::AMP}} levels or intracellular Ca²⁺.' WHERE id = '727afd84-23f9-48fe-8da0-e38bcf1282cf';
UPDATE flashcards SET cloze_text = '{{c1::Benedict''s}} reagent detects reducing sugars by forming a {{c2::red precipitate}} of Cu₂O as Cu²⁺ is reduced to Cu⁺.' WHERE id = '9935081c-40b3-4b77-a8e4-b1bb4b066406';
UPDATE flashcards SET cloze_text = 'In isotopic notation {{c1::ᴬZX}}, the {{c2::mass number (A)}} appears on top and the {{c3::atomic number (Z)}} appears on the bottom of the element symbol.' WHERE id = '6d90402f-1053-4b92-806f-214ea05d8144';
UPDATE flashcards SET cloze_text = 'After n half-lives, the fraction of the original sample remaining is {{c1::(½)ⁿ}} — so {{c2::¼}} remains after 2 half-lives and {{c3::⅛}} remains after 3.' WHERE id = '215e355b-917f-417d-823a-33ca2146f50e';
UPDATE flashcards SET cloze_text = 'Outlier rule (IQR method): any value below {{c1::Q₁ − 1.5 × IQR}} or above {{c1::Q₃ + 1.5 × IQR}} is considered an outlier.' WHERE id = '8bd518be-08fc-4a78-a507-a575eb487d1f';
UPDATE flashcards SET cloze_text = 'Multiplying powers with the same base: {{c1::add}} the exponents — Xᴬ · Xᴮ = {{c2::X⁽ᴬ⁺ᴮ⁾}}.' WHERE id = '1e19f518-e54a-4c6a-beba-c4cb4b36c330';
UPDATE flashcards SET cloze_text = 'Dividing powers with the same base: {{c1::subtract}} the exponents — Xᴬ / Xᴮ = {{c2::X⁽ᴬ⁻ᴮ⁾}}.' WHERE id = 'beea28c9-2cb5-4ee4-80d5-b82e3925c743';
UPDATE flashcards SET cloze_text = 'A power raised to a power: {{c1::multiply}} the exponents — (Xᴬ)ᴮ = {{c2::X⁽ᴬ·ᴮ⁾}}.' WHERE id = 'c712adff-d733-49e7-9bce-77b7c6c016d8';
UPDATE flashcards SET cloze_text = 'When a fraction is raised to an exponent, the exponent is {{c1::distributed to both numerator and denominator}} — (X/Y)ᴬ = Xᴬ / Yᴬ.' WHERE id = 'fda7c907-c990-42ae-bbe7-7d380c8813ba';
UPDATE flashcards SET cloze_text = 'A {{c1::negative exponent}} represents the {{c2::reciprocal}}: X⁻ᴬ = {{c3::1 / Xᴬ}}.' WHERE id = '84f961ad-9470-46b4-a3d6-291963c74242';
UPDATE flashcards SET cloze_text = 'A {{c1::fractional exponent}} A/B means the {{c2::B-th root}} of Xᴬ: X⁽ᴬ/ᴮ⁾ = ᴮ√(Xᴬ).' WHERE id = '28a5e381-16d9-416d-85ec-774f2cc567b8';
UPDATE flashcards SET cloze_text = 'The work function relates to the threshold frequency by {{c1::W = h · fT}} (Planck''s constant times the threshold frequency).' WHERE id = 'a815b72c-de2f-4ac5-88c6-dcc24a01735f';
UPDATE flashcards SET cloze_text = 'The {{c1::Rydberg formula for energy}} predicts the photon energy of a hydrogen electron transition: {{c2::E = Rₕ(1/nᵢ² − 1/nf²)}}, where nᵢ and nf are the initial and final principal quantum numbers.' WHERE id = 'eaeccf84-c20f-4c79-b5d8-22be958dfd79';
UPDATE flashcards SET cloze_text = '{{c1::Effective nuclear charge (Zeff)}} is the net positive charge actually experienced by an atom''s outermost electrons after accounting for {{c2::shielding}} by the inner-shell electrons — formally Zeff ≈ {{c3::Z − S}}, where S is the shielding constant.' WHERE id = '8c04acab-ca5b-4849-a165-5138bc535b4e';
UPDATE flashcards SET cloze_text = '{{c1::Mechanical advantage}} of a simple machine is the ratio of the output force it produces to the input force applied: {{c2::MA = Fout / Fin}}. A machine with MA = 5 lets you produce a 5 N output by applying only 1 N at the input.' WHERE id = 'a55d2eb6-82ae-4d85-88ef-2ac2d3f5a860';
UPDATE flashcards SET cloze_text = 'Newton''s law of universal gravitation: every pair of masses attracts each other with a force {{c1::Fg = Gm₁m₂/r²}}, where {{c2::G = 6.67 × 10⁻¹¹ N·m²/kg²}} is the universal gravitational constant and r is the distance between the centers of the two masses.' WHERE id = 'aa98d149-5bd4-498b-bf07-3783beef5c79';
UPDATE flashcards SET cloze_text = 'Newton''s first law (the law of {{c1::inertia}}) states that an object maintains its current state of motion — at rest if at rest, in constant velocity if moving — unless a {{c2::net external force}} changes it. Equivalently, {{c3::Fnet = 0 implies a = 0}}.' WHERE id = 'f41dff99-fefd-4e71-a3af-8265336a9a38';
UPDATE flashcards SET cloze_text = 'Gravitational potential energy near Earth''s surface is {{c1::Ug = mgh}}, where m is mass, g is the acceleration due to gravity (≈ 9.8 m/s²), and h is the {{c2::height above a chosen reference level}} (called the datum).' WHERE id = '3be96694-994f-4700-8496-af65827174ac';
UPDATE flashcards SET cloze_text = 'When {{c1::non-conservative}} forces act, mechanical energy is generally lost. The work done by non-conservative forces equals the {{c2::change in total mechanical energy}}: Wnc = ΔE = ΔK + ΔU (typically negative when friction or drag dissipates energy).' WHERE id = 'bd932b52-10d8-4caf-ac55-76f6ca3eb1f3';
UPDATE flashcards SET cloze_text = 'The {{c1::work-energy theorem}} states that the net work done on an object by all forces equals its change in kinetic energy: {{c2::Wnet = ΔK = Kf − Ki}}. This holds regardless of which kinds of forces are involved — conservative or non-conservative.' WHERE id = 'a86d4cf8-6921-4b45-b717-993179d19ada';
UPDATE flashcards SET cloze_text = 'When the action potential reaches the synaptic terminal, voltage-gated {{c1::calcium}} channels open and Ca²⁺ flows into the {{c2::presynaptic}} neuron.' WHERE id = '2bc0e0c8-e007-4514-b256-ae9ff3c667d5';
UPDATE flashcards SET cloze_text = '{{c1::IP₃}} produced by the Gq pathway diffuses to the endoplasmic reticulum and opens calcium channels there, releasing stored {{c2::Ca²⁺}} into the cytosol as a second messenger.' WHERE id = 'bdfe5fcf-cea9-41ba-a5b7-3d9058084cfb';
UPDATE flashcards SET cloze_text = '{{c1::Cofactors}} are non-protein helpers required for enzyme activity; they are typically {{c2::inorganic}} (metal ions like Zn²⁺, Mg²⁺), while {{c3::coenzymes}} are small {{c2::organic}} helpers, usually vitamin-derived.' WHERE id = '57a737b7-6bb0-46ca-9070-03fad0f9eb2a';
UPDATE flashcards SET cloze_text = 'The three most testable hexoses are {{c1::glucose}}, {{c1::fructose}}, and {{c1::galactose}}; all three share the molecular formula C₆H₁₂O₆ but differ in structure.' WHERE id = 'c8ad2248-5aa1-44cf-830f-1e262e4fa0f9';
UPDATE flashcards SET cloze_text = 'When polar bond dipoles do {{c1::not}} cancel because of asymmetric geometry, the molecule has a net {{c2::dipole moment}} and is overall polar (e.g., H₂O).' WHERE id = '1951fb4d-c409-4d64-a086-00ce09015d02';
UPDATE flashcards SET cloze_text = 'The {{c1::threshold frequency (fT)}} is the minimum incident-light frequency needed to {{c2::eject an electron}} from a given metal; it depends on the metal''s {{c3::work function}}.' WHERE id = 'a481ef53-0e5f-4db6-bee0-c1c2008fa0ee';
UPDATE flashcards SET cloze_text = 'The maximum kinetic energy of an ejected electron is {{c1::Kmax = hf − W}} — the photon''s energy minus the energy spent {{c2::escaping the metal}}.' WHERE id = '195200b4-5d0a-494d-a4d9-4075b701e322';
UPDATE flashcards SET cloze_text = 'The number of nuclei remaining at time t is {{c1::n(t) = n₀ · e⁻λᵗ}}, where n₀ is the {{c2::starting number}} and λ is the {{c3::decay constant}}.' WHERE id = '2262e229-7cf6-4e10-bf49-a4742f15ff0f';
UPDATE flashcards SET cloze_text = 'The {{c1::interquartile range (IQR)}} equals {{c2::Q₃ − Q₁}}; it captures the middle 50% of the data and is {{c3::resistant to outliers}}.' WHERE id = '86d5e636-dd68-4d82-885d-7a69f84863f9';
UPDATE flashcards SET cloze_text = 'A {{c1::box plot}} shows the {{c2::median, Q₁, Q₃, and range}}: the box spans Q₁ to Q₃ with the median as a line inside, and the whiskers extend to the {{c3::extreme values within 1.5 × IQR}} (outliers plotted separately).' WHERE id = '379b5969-06ef-4e2c-965f-6ff375128565';
UPDATE flashcards SET cloze_text = 'Log of a {{c1::power}}: log(Aᴮ) = {{c2::B · log A}}; log of a {{c1::reciprocal}}: log(1 / A) = {{c2::−log A}}.' WHERE id = '9f8cbc47-d9ce-47f1-a25c-5aae99c1d5eb';
UPDATE flashcards SET cloze_text = 'An electron in an atom is described by four quantum numbers: {{c1::principal (n)}}, {{c1::azimuthal (l)}}, {{c1::magnetic (mₗ)}}, and {{c1::spin (mₛ)}}.' WHERE id = '670951c1-8bc6-4ea4-8b7f-27ab82cbe21d';
UPDATE flashcards SET cloze_text = 'The {{c1::magnetic quantum number (mₗ)}} describes the {{c2::orientation of the orbital}} within a subshell and ranges from {{c3::−l to +l}}.' WHERE id = '19ee4ae5-6ac2-4ef6-a24c-3542a50646d1';
UPDATE flashcards SET cloze_text = 'The {{c1::spin quantum number (mₛ)}} indicates the electron''s spin direction, with only two possible values: {{c2::+1/2 or −1/2}}.' WHERE id = '0d1fdc7a-7ad3-4d8a-a61c-b0f8ab19280e';
UPDATE flashcards SET cloze_text = 'In the Arrhenius equation the exponential factor is {{c1::e⁻ᴱᵃ⁄ᴿᵀ}}, where R = {{c2::8.314 J·mol⁻¹·K⁻¹}} and T is in {{c3::kelvin}}.' WHERE id = '1dda4768-8d4a-42d9-9e1f-5b51f8f5db78';
UPDATE flashcards SET cloze_text = 'The Arrhenius equation, k = {{c1::Ae⁻ᴱᵃ⁄ᴿᵀ}}, ties a reaction''s rate constant to its {{c2::activation energy}} and to {{c3::temperature}}.' WHERE id = '49cd4cc7-1e67-403f-9dff-3dd1dc169a54';
UPDATE flashcards SET cloze_text = 'Because Eₐ sits in the exponent as e⁻ᴱᵃ⁄ᴿᵀ, a {{c1::lower}} activation energy leaves a {{c2::larger}} fraction of molecules with enough energy to react, giving a faster rate.' WHERE id = '6f892539-8aac-4fb2-a762-3c63479b9711';
UPDATE flashcards SET cloze_text = 'A {{c1::first}}-order reaction obeys rate = k[A], so doubling [A] {{c2::doubles}} the rate; the integrated law is [A]ₜ = [A]₀e⁻ᵏᵗ, a plot of {{c3::ln[A]}} versus t is linear with slope −k, and k has units of {{c4::s⁻¹}}.' WHERE id = 'd8f50a16-5e07-4c94-9617-4bf6c72e7b86';

COMMIT;
